window.__TNPSC_REGISTER_TEST__("gk", 2, [{"id":101,"subject":"gk","testNumber":2,"question":"சங்க காலச் சேர மன்னர்களின் தலைநகரம் மற்றும் முக்கியத் துறைமுக நகரங்கள் முறையே எவை?","options":["காஞ்சிபுரம்; மாமல்லபுரம் மற்றும் மயிலாப்பூர்","வஞ்சி (கரூர்); முசிறி மற்றும் தொண்டி","உறையூர்; காவிரிப்பூம்பட்டினம் மற்றும் நாகப்பட்டினம்","மதுரை; கொற்கை மற்றும் காயல்"],"correctAnswer":1,"explanation":"சங்க காலச் சேர மன்னர்கள் இன்றைய கேரளா மற்றும் தமிழகத்தின் மேற்குப் பகுதிகளை ஆட்சி செய்தனர். இவர்களின் தலைநகரம் வஞ்சி (கரூர்) ஆகும்; முசிறி மற்றும் தொண்டி ஆகியவை மேற்குக் கடற்கரையில் அமைந்த சேரர்களின் முக்கியத் துறைமுக நகரங்களாகும்.","difficulty":"medium","topic":"சங்க காலம் – சேரர்"},{"id":102,"subject":"gk","testNumber":2,"question":"சங்க காலச் சோழர்களின் அரசுச் சின்னம் மற்றும் அடையாளப் பூ முறையே எவை?","options":["நந்தி மற்றும் தாமரைப்பூ","வில் அம்பு மற்றும் பனம்பூ","மீன் மற்றும் வேப்பம்பூ","புலி மற்றும் அத்திப்பூ"],"correctAnswer":3,"explanation":"சங்க கால மூவேந்தர்களில் சோழர்களின் அரசுச் சின்னம் புலி ஆகும்; இவர்கள் அணிந்த அடையாள மாலை அத்திப்பூ மாலையாகும். சோழர்களின் உள்நாட்டுத் தலைநகரமாக உறையூரும், துறைமுகத் தலைநகரமாகப் பூம்புகாரும் (காவிரிப்பூம்பட்டினம்) விளங்கின.","difficulty":"easy","topic":"சங்க காலம் – சோழர்"},{"id":103,"subject":"gk","testNumber":2,"question":"சங்க காலப் பாண்டியர்களின் துறைமுக நகரமான 'கொற்கை' எத்தொழிலுக்கு உலகப் புகழ்பெற்றதாக விளங்கியது?","options":["இரும்பு உருக்குதல்","பட்டு நெசவு","முத்துக்குளித்தல்","கப்பல் கட்டுதல்"],"correctAnswer":2,"explanation":"தாமிரபரணி ஆறு கடலில் கலக்கும் இடத்தில் அமைந்திருந்த கொற்கை சங்க காலப் பாண்டியர்களின் முக்கியத் துறைமுகமாகும். இங்கு நடைபெற்று வந்த முத்துக்குளித்தல் பற்றிப் 'பெரிப்ளஸ்' நூலும் சங்க இலக்கியங்களும் சிறப்பாகக் குறிப்பிடுகின்றன.","difficulty":"easy","topic":"சங்க காலம் – பாண்டியர்"},{"id":104,"subject":"gk","testNumber":2,"question":"பின்வருவனவற்றுள் சங்க கால மூவேந்தர்களின் அடையாளப் பூக்களில் சரியான இணையைத் தேர்ந்தெடுக்கவும்:","options":["சேரர் – பனம்பூ; பாண்டியர் – வேப்பம்பூ","சோழர் – பனம்பூ; சேரர் – அத்திப்பூ","சேரர் – வேப்பம்பூ; பாண்டியர் – பனம்பூ","பாண்டியர் – அத்திப்பூ; சோழர் – வேப்பம்பூ"],"correctAnswer":0,"explanation":"சங்க கால மூவேந்தர்கள் தங்களின் அடையாளமாகத் தனித்தனிப் பூமாலைகளை அணிந்தனர். அதன்படி சேரர்களுக்குப் பனம்பூவும், சோழர்களுக்கு அத்திப்பூவும், பாண்டியர்களுக்கு வேப்பம்பூவும் உரிய அடையாளப் பூக்களாகும்.","difficulty":"easy","topic":"சங்க காலம் – மூவேந்தர்"},{"id":105,"subject":"gk","testNumber":2,"question":"சங்க காலப் பாண்டிய மன்னர்களின் அரசுச் சின்னம் எது?","options":["வில் அம்பு","புலி","இரட்டை மீன் (கயல்)","சிங்கம்"],"correctAnswer":2,"explanation":"பாண்டியர்களின் அரசுச் சின்னம் மீன் (இரட்டைக் கயல்) ஆகும். இவர்களின் நாணயங்களின் ஒரு பக்கத்தில் யானை வடிவமும், மறுபக்கத்தில் மீன் சின்னமும் பொறிக்கப்பட்டிருந்தன.","difficulty":"easy","topic":"சங்க காலம் – பாண்டியர்"},{"id":106,"subject":"gk","testNumber":2,"question":"இமயமலை வரை படையெடுத்துச் சென்று அங்கிருந்து கல் கொண்டு வந்து கண்ணகிக்குக் கோயில் கட்டிய சேர மன்னர் யார்?","options":["இமயவரம்பன் நெடுஞ்சேரலாதன்","சேரன் செங்குட்டுவன்","சேரல் இரும்பொறை","உதியன் சேரலாதன்"],"correctAnswer":1,"explanation":"சேரன் செங்குட்டுவன் வடஇந்தியாவின் மீது படையெடுத்து இமயமலையிலிருந்து கல் கொண்டு வந்து கங்கை நீரில் நீராட்டி கண்ணகிக்குச் சிலை வடித்துப் பத்தினி வழிபாட்டைத் தமிழகத்தில் அறிமுகப்படுத்தினார். இவரது தம்பியான இளங்கோவடிகள் சிலப்பதிகாரத்தை இயற்றினார்.","difficulty":"easy","topic":"சங்க காலம் – சேரர்"},{"id":107,"subject":"gk","testNumber":2,"question":"இமயமலையில் சேரர்களின் வில் சின்னத்தைப் பொறித்ததால் 'இமயவரம்பன்' என்ற பட்டத்தைப் பெற்ற சேர மன்னர் யார்?","options":["சேரன் செங்குட்டுவன்","செல்வக்கடுங்கோ வாழியாதன்","நெடுஞ்சேரலாதன்","பெருஞ்சேரல் இரும்பொறை"],"correctAnswer":2,"explanation":"சேர மன்னன் நெடுஞ்சேரலாதன் இமயமலை வரை படையெடுத்துச் சென்று அங்கு சேரர்களின் வில் சின்னத்தைப் பொறித்ததால் 'இமயவரம்பன் நெடுஞ்சேரலாதன்' எனப் போற்றப்பட்டார். இவரது சாதனைகளைப் பதிற்றுப்பத்து இரண்டாம் பத்து விரிவாகப் பாடுகிறது.","difficulty":"medium","topic":"சங்க காலம் – சேரர்"},{"id":108,"subject":"gk","testNumber":2,"question":"காவிரி ஆற்றின் குறுக்கே உலகப் புகழ்பெற்ற 'கல்லணை'யைக் கட்டிய சங்க காலச் சோழ மன்னர் யார்?","options":["கோச்செங்கணான்","இளஞ்சேட்சென்னி","கரிகால் வளவன்","கிள்ளிவளவன்"],"correctAnswer":2,"explanation":"சங்க காலச் சோழ மன்னர்களுள் தலைசிறந்தவரான கரிகாலன் காவிரி ஆற்றின் குறுக்கே கல்லணையைக் கட்டினார். கற்களைக் கொண்டு கட்டப்பட்ட இந்த அணை இன்றுவரை பயன்பாட்டில் உள்ள உலகின் மிகப் பழமையான நீர்ப்பாசன அணைகளில் ஒன்றாக விளங்குகிறது.","difficulty":"easy","topic":"சங்க காலம் – சோழர்"},{"id":109,"subject":"gk","testNumber":2,"question":"கரிகால் சோழன் 'வெண்ணி' என்ற இடத்தில் நடைபெற்ற போரில் யாரைத் தோற்கடித்தார்?","options":["பல்லவர்கள் மற்றும் களப்பிரர்கள்","சேரர் மற்றும் ஒன்பது குறுநில மன்னர்கள் மட்டும்","சாதவாகனர்கள் மற்றும் கதம்பர்கள்","சேரர், பாண்டியர் மற்றும் பதினொரு வேளிர் தலைவர்கள்"],"correctAnswer":3,"explanation":"தஞ்சாவூர் பகுதியில் அமைந்த வெண்ணிப் போர்க்களத்தில் கரிகாலன் தன்னை எதிர்த்த சேரர், பாண்டியர் மற்றும் அவர்களுக்குத் துணை நின்ற பதினொரு வேளிர் தலைவர்களின் கூட்டுப்படையை வென்றார். மேலும் வாகைப்பறந்தலைப் போரில் ஒன்பது மன்னர்களையும் இவர் தோற்கடித்தார்.","difficulty":"medium","topic":"சங்க காலம் – சோழர்"},{"id":110,"subject":"gk","testNumber":2,"question":"'தலையாலங்கானத்துச் செருவென்ற' என்ற சிறப்புப் பெயர் பெற்ற பாண்டிய மன்னர் யார்?","options":["பாண்டியன் நெடுஞ்செழியன்","நன்மாறன்","முதுகுடுமிப் பெருவழுதி","ஆரியப்படை கடந்த நெடுஞ்செழியன்"],"correctAnswer":0,"explanation":"இளம் வயதிலேயே பாண்டியன் நெடுஞ்செழியன் தன்னை எதிர்த்துப் போரிட்ட சேரர், சோழர் மற்றும் ஐந்து வேளிர் குலத் தலைவர்களின் கூட்டுப்படையைத் தலையாலங்கானம் என்ற இடத்தில் தோற்கடித்தார். இதனால் அவர் 'தலையாலங்கானத்துச் செருவென்ற நெடுஞ்செழியன்' எனப் போற்றப்பட்டார்.","difficulty":"easy","topic":"சங்க காலம் – பாண்டியர்"},{"id":111,"subject":"gk","testNumber":2,"question":"சங்க காலச் சேர மன்னர்களில் தன் பெயரில் நாணயங்களை வெளியிட்டவர் யார்?","options":["சேரல் இரும்பொறை","நார்முடிச்சேரல்","ஆடுகோட்பாட்டுச் சேரலாதன்","குட்டுவன் கோதை"],"correctAnswer":0,"explanation":"சேர மன்னன் சேரல் இரும்பொறை தன் பெயரில் நாணயங்களை வெளியிட்டதாகச் சமச்சீர் கல்வி வரலாற்றுப் பாடநூல் குறிப்பிடுகிறது. கரூர் பகுதியில் கிடைத்த சேரர் கால நாணயங்கள் இவர்களின் ஆட்சி மற்றும் பொருளாதார வளத்தை உறுதிப்படுத்துகின்றன.","difficulty":"medium","topic":"சங்க காலம் – சேரர்"},{"id":112,"subject":"gk","testNumber":2,"question":"பறம்புமலையை ஆட்சி செய்தவரும், 'முல்லைக்குத் தேர் கொடுத்த வள்ளல்' எனப் போற்றப்படுபவருமான கடையெழு வள்ளல் யார்?","options":["காரி","பாரி","ஆய் அண்டிரன்","பேகன்"],"correctAnswer":1,"explanation":"கடையெழு வள்ளல்களில் ஒருவரான வேள்பாரி பறம்புமலையை ஆட்சி செய்தார். கொழுகொம்பின்றித் தவித்த முல்லைக் கொடிக்குத் தான் ஊர்ந்து சென்ற தேரையே நிறுத்திவிட்டுச் சென்றதால் 'முல்லைக்குத் தேர் கொடுத்த பாரி' எனப் புலவர் கபிலரால் போற்றப்பட்டார்.","difficulty":"easy","topic":"சங்க காலம் – கடையெழு வள்ளல்கள்"},{"id":113,"subject":"gk","testNumber":2,"question":"குளிரால் நடுங்கிய மயிலுக்குத் தனது விலைமதிப்பற்ற போர்வையைப் போர்த்திய கடையெழு வள்ளல் யார்?","options":["வையாவிக் கோப்பெரும் பேகன்","வல்வில் ஓரி","கண்டீரக் கோப்பெருநள்ளி","அதியமான் நெடுமான் அஞ்சி"],"correctAnswer":0,"explanation":"பழனிமலை (பொதினி) பகுதியை ஆட்சி செய்த வையாவிக் கோப்பெரும் பேகன், காட்டில் மழையில் நனைந்து குளிரால் ஆடிய மயிலுக்குத் தனது உயர்ந்த போர்வையைக் கொடுத்தார். இவரது கொடைச் சிறப்பைப் பரணர் மற்றும் கபிலர் ஆகியோர் புறநானூற்றில் பாடியுள்ளனர்.","difficulty":"easy","topic":"சங்க காலம் – கடையெழு வள்ளல்கள்"},{"id":114,"subject":"gk","testNumber":2,"question":"சாவாமை தரும் அரிய நெல்லிக்கனியைத் தான் உண்ணாமல் தமிழ்ப் புலவர் ஔவையாருக்கு வழங்கிய வள்ளல் யார்?","options":["வேள்பாரி","ஆய் அண்டிரன்","அதியமான் நெடுமான் அஞ்சி","மலையமான் திருமுடிக்காரி"],"correctAnswer":2,"explanation":"தகடூரை (இன்றைய தருமபுரி) தலைநகராகக் கொண்டு ஆட்சி செய்த அதியமான் நெடுமான் அஞ்சி, அரிய கருநெல்லிக்கனியைத் தமிழின் வளர்ச்சிக்காக ஔவையார் நீடுழி வாழ வேண்டும் என்ற உயரிய எண்ணத்துடன் அவருக்கு வழங்கினார்.","difficulty":"easy","topic":"சங்க காலம் – கடையெழு வள்ளல்கள்"},{"id":115,"subject":"gk","testNumber":2,"question":"நீலநாகம் நல்கிய அரிய ஆடையை (கலிங்கம்) ஆலமரத்தின் கீழ் வீற்றிருக்கும் சிவபெருமானுக்கு வழங்கிய கடையெழு வள்ளல் யார்?","options":["பேகன்","ஓரி","நள்ளி","ஆய் அண்டிரன்"],"correctAnswer":3,"explanation":"பொதிய மலையை ஆட்சி செய்த ஆய் அண்டிரன், நீலநாகம் கொடுத்த அரிய ஆடையை ஆலமரத்தின் கீழ் உள்ள சிவபெருமானுக்குக் காணிக்கையாக வழங்கினார் எனச் சிறுபாணாற்றுப்படை கூறுகிறது. இவர் யானைகளைப் பரிசாக வழங்குவதில் வல்லவராக விளங்கினார்.","difficulty":"medium","topic":"சங்க காலம் – கடையெழு வள்ளல்கள்"},{"id":116,"subject":"gk","testNumber":2,"question":"கடையெழு வள்ளல்களையும் அவர்கள் ஆட்சி செய்த மலைப்பகுதிகளையும் சரியாகப் பொருத்துக:\n1. ஓரி – அ. முள்ளூர் மலை\n2. காரி – ஆ. கொல்லிமலை\n3. நள்ளி – இ. பறம்புமலை\n4. பாரி – ஈ. தோட்டி மலை","options":["1-ஆ, 2-அ, 3-ஈ, 4-இ","1-ஆ, 2-ஈ, 3-அ, 4-இ","1-அ, 2-ஆ, 3-இ, 4-ஈ","1-இ, 2-அ, 3-ஈ, 4-ஆ"],"correctAnswer":0,"explanation":"கடையெழு வள்ளல்களின் ஆட்சிப் பகுதிகள்: வல்வில் ஓரி – கொல்லிமலை (நாமக்கல்), மலையமான் திருமுடிக்காரி – முள்ளூர் மலை (திருக்கோவிலூர் பகுதி), கண்டீரக் கோப்பெருநள்ளி – தோட்டி மலை, வேள்பாரி – பறம்புமலை (பிரான்மலை). எனவே 1-ஆ, 2-அ, 3-ஈ, 4-இ என்பது சரியான பொருத்தமாகும்.","difficulty":"hard","topic":"சங்க காலம் – கடையெழு வள்ளல்கள்"},{"id":117,"subject":"gk","testNumber":2,"question":"சங்க காலக் காவிரிப்பூம்பட்டினத்தின் (பூம்புகார்) வணிக வளத்தையும் கரிகாலனின் சிறப்பையும் விரிவாகக் கூறும் பத்துப்பாட்டு நூல் எது?","options":["மலைபடுகடாம்","நெடுநல்வாடை","மதுரைக்காஞ்சி","பட்டினப்பாலை"],"correctAnswer":3,"explanation":"கடியலூர் உருத்திரங்கண்ணனார் இயற்றிய 'பட்டினப்பாலை' நூல், சோழர்களின் துறைமுக நகரமான காவிரிப்பூம்பட்டினத்தில் நடைபெற்ற உள்நாட்டு மற்றும் கடல் கடந்த வணிகம், சுங்கவரி வசூல் மற்றும் கரிகால் சோழனின் ஆட்சிச் சிறப்பை விரிவாக எடுத்துரைக்கிறது.","difficulty":"medium","topic":"சங்க காலம் – வணிகம்"},{"id":118,"subject":"gk","testNumber":2,"question":"சேரர்களின் துறைமுகமான முசிறியை 'இந்தியாவின் முதல் பேரங்காடி' (First Emporium of India) என்று தனது 'இயற்கை வரலாறு' நூலில் குறிப்பிட்ட ரோமானிய அறிஞர் யார்?","options":["மெகஸ்தனிஸ்","மூத்த பிளினி","தாலமி","ஸ்டிராபோ"],"correctAnswer":1,"explanation":"ரோமானிய வரலாற்றாசிரியரான மூத்த பிளினி (Pliny the Elder) தனது 'இயற்கை வரலாறு' (Natural History) என்ற நூலில் முசிறித் துறைமுகத்தை 'இந்தியாவின் முதல் பேரங்காடி' எனக் குறிப்பிட்டுள்ளார். மேலும் மிளகு வணிகத்தால் ரோம் நாட்டின் தங்கம் இந்தியாவிற்குப் பெருமளவில் செல்வதாகவும் அவர் கவலை தெரிவித்துள்ளார்.","difficulty":"medium","topic":"சங்க காலம் – ரோமானியத் தொடர்பு"},{"id":119,"subject":"gk","testNumber":2,"question":"சங்க காலத்தில் மதுரை மற்றும் புகார் நகரங்களில் செயல்பட்ட பகல் நேர மற்றும் இரவு நேரக் கடைத்தெருக்கள் முறையே எவ்வாறு அழைக்கப்பட்டன?","options":["நாளங்காடி மற்றும் மருவூர்ப்பாக்கம்","அல்லங்காடி மற்றும் நாளங்காடி","பட்டினப்பாக்கம் மற்றும் அல்லங்காடி","நாளங்காடி மற்றும் அல்லங்காடி"],"correctAnswer":3,"explanation":"சங்க கால நகரங்களில் பகல் நேரத்தில் செயல்பட்ட அங்காடி 'நாளங்காடி' என்றும், இரவு நேரத்தில் செயல்பட்ட அங்காடி 'அல்லங்காடி' என்றும் அழைக்கப்பட்டன. பெண்கள் இரவு நேரத்திலும் அச்சமின்றி அல்லங்காடிக்குச் சென்று பொருட்களை வாங்கும் அளவுக்குப் பாதுகாப்பு நிலவியதாக மதுரைக்காஞ்சி கூறுகிறது.","difficulty":"medium","topic":"சங்க காலம் – வணிகம்"},{"id":120,"subject":"gk","testNumber":2,"question":"சங்க காலத் தமிழகத்திற்கும் ரோம் பேரரசுக்கும் இடையிலான வணிகத் தொடர்பு குறித்த பின்வரும் கூற்றுகளில் தவறானது எது?","options":["தமிழகத்திலிருந்து மிளகு, முத்து, தந்தம் மற்றும் மெல்லிய பருத்தி ஆடைகள் ஏற்றுமதி செய்யப்பட்டன.","சங்க காலத்தில் ரோமானியர்களுடன் தரைவழி வணிகம் மட்டுமே நடைபெற்றது; கடல்வழி வணிகம் நடைபெறவில்லை.","ரோமானியர்கள் தமிழகத்திற்குத் தங்கம், வெள்ளி நாணயங்கள் மற்றும் மதுபான ஜாடிகளைக் கொண்டு வந்தனர்.","முசிறியில் ரோமானியர்கள் அகஸ்டஸ் மன்னருக்குக் கோயில் கட்டியிருந்தனர்."],"correctAnswer":1,"explanation":"சங்க காலத் தமிழகத்திற்கும் ரோம் நாட்டிற்கும் இடையே பருவக்காற்றைப் (ஹிப்பாலஸ் கண்டுபிடித்த தென்மேற்குப் பருவக்காற்று) பயன்படுத்தி விரிவான கடல்வழி வணிகமே நடைபெற்றது. எனவே கடல்வழி வணிகம் நடைபெறவில்லை என்ற கூற்று தவறானதாகும்.","difficulty":"hard","topic":"சங்க காலம் – ரோமானியத் தொடர்பு"},{"id":121,"subject":"gk","testNumber":2,"question":"சங்க காலத் தமிழகத்தில் போரில் வீரமரணம் அடைந்த வீரர்களின் நினைவாக நடப்பட்ட கற்கள் எவ்வாறு அழைக்கப்பட்டன?","options":["நடுகல் (வீரக்கல்)","கல்திட்டை","கல்வட்டம்","குத்துக்கல்"],"correctAnswer":0,"explanation":"சங்க கால மக்கள் போரில் விழுப்புண்பட்டு உயிர் நீத்த வீரர்களைப் போற்றும் விதமாக 'நடுகல்' அல்லது 'வீரக்கல்' நட்டு வழிபட்டனர். அக்கல்லில் வீரரின் பெயரும் அவரது வீரச்செயலும் பொறிக்கப்பட்டன; இது குறித்துத் தொல்காப்பியம் விரிவாகக் கூறுகிறது.","difficulty":"easy","topic":"சங்க காலம் – சமூகம் & பண்பாடு"},{"id":122,"subject":"gk","testNumber":2,"question":"சங்க கால ஐந்திணைகளில் 'நெய்தல்' நிலத்திற்குரிய தெய்வம் மற்றும் முதன்மைத் தொழில் முறையே எவை?","options":["திருமால் – ஆனிரை மேய்த்தல்","வருணன் – மீன் பிடித்தல் மற்றும் உப்பு விளைவித்தல்","இந்திரன் – வேளாண்மை","முருகன் – வேட்டையாடுதல்"],"correctAnswer":1,"explanation":"கடலும் கடல் சார்ந்த இடமுமான நெய்தல் நிலத்தின் தெய்வம் வருணன் ஆகும்; இந்நில மக்களான பரதவர் மற்றும் நுளையர்களின் முக்கியத் தொழில் மீன் பிடித்தல் மற்றும் உப்பு விளைவித்தல் ஆகும். குறிஞ்சி-முருகன், முல்லை-திருமால், மருதம்-இந்திரன், பாலை-கொற்றவை ஆகியவை பிற திணைத் தெய்வங்களாகும்.","difficulty":"medium","topic":"சங்க காலம் – சமூகம் & பண்பாடு"},{"id":123,"subject":"gk","testNumber":2,"question":"சங்க கால ஆட்சியமைப்பில் மன்னருக்கு ஆலோசனை வழங்கிய 'ஐம்பெருங்குழு' உறுப்பினர்களுள் இடம்பெறாதவர் யார்?","options":["அமைச்சர்","ஒற்றர்","படைத்தலைவர்","கரணத்தியலவர்"],"correctAnswer":3,"explanation":"சங்க கால மன்னருக்கு உதவிய ஐம்பெருங்குழுவில் அமைச்சர், புரோகிதர் (சடங்கு நடத்துவோர்), படைத்தலைவர், தூதர், ஒற்றர் ஆகிய ஐவர் இடம்பெற்றிருந்தனர். 'கரணத்தியலவர்' (கணக்காளர்) என்பவர் 'எண்பேராயம்' என்ற மற்றொரு ஆலோசனைக் குழுவைச் சேர்ந்தவர் ஆவார்.","difficulty":"hard","topic":"சங்க காலம் – ஆட்சிமுறை"},{"id":124,"subject":"gk","testNumber":2,"question":"களப்பிரர்கள் ஆட்சிக் காலத்தில் (கி.பி. 3ஆம் – 6ஆம் நூற்றாண்டு) தமிழில் தோன்றிய முக்கிய இலக்கியத் தொகுப்பு எது?","options":["பதினெண்கீழ்க்கணக்கு நூல்கள்","பன்னிரு திருமுறை","பத்துப்பாட்டு","எட்டுத்தொகை"],"correctAnswer":0,"explanation":"களப்பிரர்கள் காலம் 'இருண்ட காலம்' என முன்னர் கருதப்பட்டாலும், அக்காலத்தில்தான் திருக்குறள், நாலடியார் உள்ளிட்ட பதினெண்கீழ்க்கணக்கு அறநூல்களும், சிலப்பதிகாரம், மணிமேகலை போன்ற பெருங்காப்பியங்களும் தோன்றித் தமிழ் இலக்கியத்தை வளப்படுத்தின.","difficulty":"medium","topic":"களப்பிரர் காலம்"},{"id":125,"subject":"gk","testNumber":2,"question":"களப்பிரர் ஆட்சிக் காலத்தில் கி.பி. 470-இல் மதுரையில் 'திரமிள சங்கம்' என்ற சமண சங்கத்தை நிறுவிய சமணத் துறவி யார்?","options":["பத்திரபாகு","அப்பூதி அடிகள்","புத்ததத்தர்","வஜ்ரநந்தி"],"correctAnswer":3,"explanation":"களப்பிரர்கள் சமணம் மற்றும் பௌத்த சமயங்களுக்குப் பேராதரவு அளித்தனர். இவர்களது காலத்தில் கி.பி. 470-இல் வஜ்ரநந்தி என்ற சமணத் துறவி மதுரையில் 'திரமிள சங்கம்' என்ற அமைப்பை நிறுவினார்; மேலும் பௌத்த அறிஞர் புத்ததத்தர் களப்பிர மன்னர் அச்சுத விக்கிராந்தனைப் புகழ்ந்துள்ளார்.","difficulty":"hard","topic":"களப்பிரர் காலம்"},{"id":126,"subject":"gk","testNumber":2,"question":"களப்பிரர்களை வென்று காஞ்சிபுரத்தைத் தலைநகராகக் கொண்டு பிற்காலப் பல்லவ வம்சத்தைத் தோற்றுவித்தவர் யார்?","options":["இரண்டாம் பரமேஸ்வரவர்மன்","சிம்மவிஷ்ணு","முதலாம் மகேந்திரவர்மன்","முதலாம் நரசிம்மவர்மன்"],"correctAnswer":1,"explanation":"பிற்காலப் பல்லவப் பேரரசைத் தோற்றுவித்தவர் சிம்மவிஷ்ணு (கி.பி. 575–600) ஆவார். இவர் களப்பிரர்களை அழித்துச் சோழ மண்டலம் வரை பல்லவ ஆட்சியை விரிவுபடுத்தியதோடு 'அவனிசிம்மன்' என்ற பட்டத்தையும் பெற்றார்.","difficulty":"medium","topic":"பல்லவர்கள்"},{"id":127,"subject":"gk","testNumber":2,"question":"'மத்தவிலாசப் பிரகசனம்' என்ற நகைச்சுவை சமஸ்கிருத நாடக நூலை இயற்றிய பல்லவ மன்னர் யார்?","options":["முதலாம் மகேந்திரவர்மன்","மூன்றாம் நந்திவர்மன்","சிம்மவிஷ்ணு","இரண்டாம் நரசிம்மவர்மன்"],"correctAnswer":0,"explanation":"பல்கலை வித்தகரான முதலாம் மகேந்திரவர்மன் (கி.பி. 600–630) 'மத்தவிலாசப் பிரகசனம்' (குடிகாரர்களின் மகிழ்ச்சி) என்ற சமஸ்கிருத நாடக நூலை இயற்றினார். இந்நூல் அக்கால பௌத்த, காபாலிக சமயப் பிரிவினரின் செயல்களை நகைச்சுவையாகச் சித்தரிக்கிறது.","difficulty":"medium","topic":"பல்லவர்கள்"},{"id":128,"subject":"gk","testNumber":2,"question":"'விசித்திரசித்தன்', 'சித்திரகாரப் புலி', 'மத்தவிலாசன்', 'சங்கீரண ஜதி' ஆகிய சிறப்புப் பட்டங்களைப் பெற்ற பல்லவ மன்னர் யார்?","options":["இராஜசிம்மன்","முதலாம் மகேந்திரவர்மன்","முதலாம் நரசிம்மவர்மன்","இரண்டாம் நந்திவர்மன்"],"correctAnswer":1,"explanation":"முதலாம் மகேந்திரவர்மன் கட்டிடக்கலை, ஓவியம், இசை, இலக்கியம் ஆகிய துறைகளில் சிறந்து விளங்கியதால் விசித்திரசித்தன் (புதிய சிந்தனையாளர்), சித்திரகாரப் புலி (ஓவியத்தில் வல்லவர்), சங்கீரண ஜதி (இசைத்தாளம் அறிந்தவர்), சேத்தகாரி (கோயில் கட்டுபவர்) எனப் பல பட்டங்களைப் பெற்றார்.","difficulty":"medium","topic":"பல்லவர்கள்"},{"id":129,"subject":"gk","testNumber":2,"question":"முதலாம் மகேந்திரவர்மனைச் சமண சமயத்திலிருந்து சைவ சமயத்திற்கு மாற்றிய சைவ நாயன்மார் யார்?","options":["திருஞானசம்பந்தர்","திருநாவுக்கரசர் (அப்பர்)","மாணிக்கவாசகர்","சுந்தரர்"],"correctAnswer":1,"explanation":"தொடக்கத்தில் சமண சமயத்தைப் பின்பற்றிய முதலாம் மகேந்திரவர்மன், திருநாவுக்கரசரின் (அப்பர்) செல்வாக்கால் சைவ சமயத்திற்கு மாறினார். அதன் பின்னர் சிவன் கோயில்களைக் குடைவரை முறையில் அமைப்பதில் மிகுந்த ஆர்வம் காட்டினார்.","difficulty":"easy","topic":"பல்லவர்கள்"},{"id":130,"subject":"gk","testNumber":2,"question":"சாளுக்கிய மன்னன் இரண்டாம் புலிகேசியைத் தோற்கடித்து வாதாபியைத் தீக்கிரையாக்கி 'வாதாபிகொண்டான்' என்ற பட்டத்தைப் பெற்ற பல்லவ மன்னர் யார்?","options":["அபராஜிதவர்மன்","முதலாம் பரமேஸ்வரவர்மன்","முதலாம் நரசிம்மவர்மன்","முதலாம் மகேந்திரவர்மன்"],"correctAnswer":2,"explanation":"முதலாம் நரசிம்மவர்மன் (மாமல்லன்) தனது தந்தை மகேந்திரவர்மனின் தோல்விக்குப் பழிவாங்கும் விதமாக இரண்டாம் புலிகேசியை மணிமங்கலம், பரியளம், சூரமாரம் ஆகிய போர்களில் வென்று வாதாபியைக் கைப்பற்றினார். இதனால் அவர் 'வாதாபிகொண்டான்' என்ற பட்டத்தைப் பெற்றார்.","difficulty":"easy","topic":"பல்லவர்கள்"},{"id":131,"subject":"gk","testNumber":2,"question":"முதலாம் நரசிம்மவர்மனின் படைத்தளபதியாக இருந்து வாதாபிப் போரில் வெற்றி பெற்று, பின்னாளில் 'சிறுத்தொண்ட நாயனார்' எனப் போற்றப்பட்டவர் யார்?","options":["உதயசந்திரன்","நந்திவர்மன்","பரஞ்சோதி","நம்பி ஆரூரர்"],"correctAnswer":2,"explanation":"முதலாம் நரசிம்மவர்மனின் தலைமைப் படைத்தளபதியான பரஞ்சோதி கி.பி. 642-இல் வாதாபிப் படையெடுப்பைத் தலைமையேற்று நடத்தினார். வாதாபியிலிருந்து கணபதி சிலையைக் கொண்டுவந்து திருச்செங்காட்டங்குடியில் நிறுவி, பின்னர் 63 நாயன்மார்களுள் ஒருவரான சிறுத்தொண்டராகப் போற்றப்பட்டார்.","difficulty":"medium","topic":"பல்லவர்கள்"},{"id":132,"subject":"gk","testNumber":2,"question":"முதலாம் நரசிம்மவர்மன் ஆட்சிக் காலத்தில் (கி.பி. 640) காஞ்சிபுரத்திற்கு வருகை தந்த சீனப் பயணி யார்?","options":["மார்க்கோ போலோ","இட்சிங்","யுவான் சுவாங்","பாஹியான்"],"correctAnswer":2,"explanation":"சீன பௌத்தப் பயணியான யுவான் சுவாங் முதலாம் நரசிம்மவர்மனின் காலத்தில் காஞ்சிபுரத்திற்கு வருகை தந்தார். காஞ்சிபுரத்தில் நூற்றுக்கும் மேற்பட்ட பௌத்த மடாலயங்களும் பத்தாயிரம் பௌத்தத் துறவிகளும் இருந்ததாகவும், அங்குள்ள மக்கள் கல்வி, நேர்மை மற்றும் வீரத்தில் சிறந்து விளங்கினர் என்றும் தனது 'சியூகி' நூலில் குறிப்பிட்டுள்ளார்.","difficulty":"medium","topic":"பல்லவர்கள்"},{"id":133,"subject":"gk","testNumber":2,"question":"காஞ்சிபுரத்தில் உள்ள புகழ்பெற்ற 'கைலாசநாதர் கோயிலை'க் கட்டிய பல்லவ மன்னர் யார்?","options":["இரண்டாம் நந்திவர்மன்","இரண்டாம் நரசிம்மவர்மன் (இராஜசிம்மன்)","முதலாம் மகேந்திரவர்மன்","முதலாம் நரசிம்மவர்மன்"],"correctAnswer":1,"explanation":"இரண்டாம் நரசிம்மவர்மன் எனப்படும் இராஜசிம்மன் (கி.பி. 700–728) மணற்கற்களைக் கொண்டு காஞ்சிபுரம் கைலாசநாதர் கோயிலை (இராஜசிம்மேஸ்வரம்) கட்டினார். இது பல்லவர் காலக் கட்டுமானக் கோயில்களுக்குச் சிறந்த எடுத்துக்காட்டாகும்.","difficulty":"easy","topic":"பல்லவர்கள்"},{"id":134,"subject":"gk","testNumber":2,"question":"பல்லவர் காலக் கோயில் கட்டிடக்கலையின் நான்கு பாணிகளையும் அவற்றுக்குரிய மன்னர்களையும் சரியாகப் பொருத்துக:\n1. குடைவரைக் கோயில்கள் – அ. முதலாம் நரசிம்மவர்மன்\n2. ஒற்றைக்கல் ரதங்கள் – ஆ. முதலாம் மகேந்திரவர்மன்\n3. கட்டுமானக் கோயில்கள் (கடற்கரைக் கோயில்) – இ. இரண்டாம் நந்திவர்மன்\n4. வைகுண்டப் பெருமாள் கோயில் – ஈ. இரண்டாம் நரசிம்மவர்மன் (இராஜசிம்மன்)","options":["1-அ, 2-ஆ, 3-இ, 4-ஈ","1-ஈ, 2-அ, 3-ஆ, 4-இ","1-ஆ, 2-ஈ, 3-அ, 4-இ","1-ஆ, 2-அ, 3-ஈ, 4-இ"],"correctAnswer":3,"explanation":"பல்லவர் கட்டிடக்கலை நான்கு நிலைகளாக வளர்ந்தது: முதலாம் மகேந்திரவர்மன் – குடைவரைக் கோயில்கள், முதலாம் நரசிம்மவர்மன் (மாமல்லன்) – மாமல்லபுரம் ஒற்றைக்கல் ரதங்கள் (பஞ்ச பாண்டவர் ரதங்கள்) மற்றும் மண்டபங்கள், இராஜசிம்மன் – கடற்கரைக் கோயில் & கைலாசநாதர் கோயில், இரண்டாம் நந்திவர்மன் – காஞ்சி வைகுண்டப் பெருமாள் கோயில்.","difficulty":"hard","topic":"பல்லவர்கள் – கட்டிடக்கலை"},{"id":135,"subject":"gk","testNumber":2,"question":"'செங்கல், மரம், உலோகம், சுண்ணாம்பு ஆகிய எதுவுமின்றி பிரம்மா, விஷ்ணு, சிவன் ஆகிய மும்மூர்த்திகளுக்காகக் கோயில் அமைத்தேன்' எனக் குறிப்பிடும் மண்டகப்பட்டுக் கல்வெட்டு யாருடையது?","options":["சிம்மவிஷ்ணு","முதலாம் நரசிம்மவர்மன்","முதலாம் மகேந்திரவர்மன்","இராஜசிம்மன்"],"correctAnswer":2,"explanation":"விழுப்புரம் மாவட்டத்தில் உள்ள மண்டகப்பட்டு குடைவரைக் கோயில் கல்வெட்டு முதலாம் மகேந்திரவர்மனால் வெட்டப்பட்டது. இதில் அவர் தன்னை 'விசித்திரசித்தன்' எனக் குறிப்பிட்டு, செங்கல், மரம், உலோகம், சுண்ணாம்பு இன்றிப் பாறையைக் குடைந்து கோயில் அமைத்ததைப் பெருமையுடன் பதிவு செய்துள்ளார்.","difficulty":"medium","topic":"பல்லவர்கள் – கல்வெட்டு"},{"id":136,"subject":"gk","testNumber":2,"question":"பல்லவர் காலத்தில் காஞ்சிபுரத்தில் செயல்பட்ட 'கடிகை' என்பது எதைக் குறித்தது?","options":["நீர்ப்பாசனத் துறை","வணிகக் குழுமம்","உயர்கல்வி நிறுவனம்","படைப்பயிற்சி மையம்"],"correctAnswer":2,"explanation":"பல்லவர் காலத்தில் காஞ்சிபுரத்தில் அமைந்திருந்த 'கடிகை' புகழ்பெற்ற உயர்கல்வி நிறுவனமாகத் திகழ்ந்தது. திக்நாகர், தர்மபாலர் போன்ற புகழ்பெற்ற அறிஞர்கள் காஞ்சி கடிகையில் கல்வி பயின்றனர்; கதம்ப வம்சத்தை நிறுவிய மயூரசர்மனும் இங்கு வேதக் கல்வி கற்றார்.","difficulty":"medium","topic":"பல்லவர்கள் – கல்வி & பண்பாடு"},{"id":137,"subject":"gk","testNumber":2,"question":"இரண்டாம் நரசிம்மவர்மன் (இராஜசிம்மன்) அவையில் இருந்தவரும் 'தசகுமார சரிதம்' மற்றும் 'காவியாதர்சம்' ஆகிய சமஸ்கிருத நூல்களை இயற்றியவருமான அறிஞர் யார்?","options":["தண்டி","பெருந்தேவனார்","பாரவி","அப்பர்"],"correctAnswer":0,"explanation":"புகழ்பெற்ற சமஸ்கிருத அறிஞரான தண்டி இரண்டாம் நரசிம்மவர்மன் (இராஜசிம்மன்) அவையை அலங்கரித்தார்; இவர் 'தசகுமார சரிதம்', 'காவியாதர்சம்' ஆகிய நூல்களை இயற்றினார். 'கிராதார்ஜுனியம்' நூலை இயற்றிய பாரவி சிம்மவிஷ்ணுவின் அவையில் இருந்தார்.","difficulty":"medium","topic":"பல்லவர்கள் – இலக்கியம்"},{"id":138,"subject":"gk","testNumber":2,"question":"முத்தரையர்களிடமிருந்து தஞ்சாவூரைக் கைப்பற்றி கி.பி. 850-இல் பிற்காலச் சோழப் பேரரசை நிறுவியவர் யார்?","options":["சுந்தர சோழன்","முதலாம் பராந்தக சோழன்","விஜயாலய சோழன்","முதலாம் ஆதித்த சோழன்"],"correctAnswer":2,"explanation":"பல்லவர்களின் சிற்றரசராக இருந்த விஜயாலய சோழன் கி.பி. 850-ஆம் ஆண்டில் முத்தரையர்களிடமிருந்து தஞ்சாவூரைக் கைப்பற்றி அதைத் தலைநகராக்கிப் பிற்காலச் சோழப் பேரரசிற்கு அடித்தளமிட்டார். இவர் தஞ்சாவூரில் நிசும்பசூதனி அம்மன் கோயிலையும் கட்டினார்.","difficulty":"medium","topic":"பிற்காலச் சோழர்கள்"},{"id":139,"subject":"gk","testNumber":2,"question":"சிதம்பரம் நடராஜர் கோயிலின் விமானத்திற்குப் பொற்கூரை வேய்ந்து 'பொன் வேய்ந்த சோழன்' என அழைக்கப்பட்ட சோழ மன்னர் யார்?","options":["முதலாம் ஆதித்தன்","விஜயாலய சோழன்","முதலாம் இராஜராஜ சோழன்","முதலாம் பராந்தக சோழன்"],"correctAnswer":3,"explanation":"முதலாம் பராந்தக சோழன் (கி.பி. 907–955) பாண்டிய மன்னன் இரண்டாம் இராஜசிம்மனைத் தோற்கடித்து 'மதுரைகொண்டான்' என்ற பட்டத்தைப் பெற்றார். இவர் சிதம்பரம் நடராஜர் கோயில் சிற்றம்பலத்திற்குப் பொற்கூரை வேய்ந்ததால் 'பொன் வேய்ந்த சோழன்' எனப் போற்றப்பட்டார்.","difficulty":"medium","topic":"பிற்காலச் சோழர்கள்"},{"id":140,"subject":"gk","testNumber":2,"question":"பிற்காலச் சோழர்களின் கிராம உள்ளாட்சி முறையான 'குடவோலை முறை' பற்றி விரிவாகத் தெரிவிக்கும் கல்வெட்டு எது?","options":["அன்பில் செப்பேடு","மண்டகப்பட்டுக் கல்வெட்டு","உத்திரமேரூர் கல்வெட்டு","திருவாலங்காட்டுச் செப்பேடு"],"correctAnswer":2,"explanation":"காஞ்சிபுரம் மாவட்டத்தில் உள்ள உத்திரமேரூர் கல்வெட்டுகள் (கி.பி. 919 மற்றும் கி.பி. 921) முதலாம் பராந்தக சோழனின் ஆட்சிக் காலத்தைச் சேர்ந்தவை. இவை சதுர்வேதிமங்கலம் எனப்பட்ட பிராமணக் கிராமங்களின் சபை உறுப்பினர்களைக் 'குடவோலை முறை' மூலம் தேர்ந்தெடுக்கும் விதிகளை விரிவாகக் கூறுகின்றன.","difficulty":"easy","topic":"பிற்காலச் சோழர்கள் – உள்ளாட்சி"},{"id":141,"subject":"gk","testNumber":2,"question":"உத்திரமேரூர் கல்வெட்டின்படி குடவோலை முறையில் கிராம வாரிய உறுப்பினராவதற்குரிய வயது வரம்பு என்ன?","options":["35 முதல் 70 வயது வரை","30 முதல் 65 வயது வரை","25 முதல் 60 வயது வரை","40 முதல் 75 வயது வரை"],"correctAnswer":0,"explanation":"உத்திரமேரூர் கல்வெட்டின்படி வாரிய உறுப்பினராகப் போட்டியிடுபவர் 35 முதல் 70 வயதுக்கு உட்பட்டவராக இருக்க வேண்டும். மேலும் கால் வேலிக்கும் அதிகமான வரி செலுத்தும் நிலம், சொந்த நிலத்தில் கட்டிய வீடு, வேத மற்றும் மந்திர அறிவு, கடந்த மூன்று ஆண்டுகள் எந்த வாரியத்திலும் உறுப்பினராக இராதவராகவும் இருக்க வேண்டும்.","difficulty":"hard","topic":"பிற்காலச் சோழர்கள் – உள்ளாட்சி"},{"id":142,"subject":"gk","testNumber":2,"question":"பிற்காலப் பல்லவ மன்னர் அபராஜிதவர்மனைப் போரில் வென்று தொண்டை மண்டலத்தைச் சோழப் பேரரசுடன் இணைத்தவர் யார்?","options":["கண்டராதித்த சோழன்","முதலாம் ஆதித்த சோழன்","விஜயாலய சோழன்","உத்தம சோழன்"],"correctAnswer":1,"explanation":"விஜயாலய சோழனின் மகனான முதலாம் ஆதித்த சோழன் (கி.பி. 871–907) கி.பி. 893-இல் பல்லவ மன்னன் அபராஜிதவர்மனைப் போரில் கொன்று தொண்டை மண்டலத்தைக் கைப்பற்றினார். இதன்மூலம் பல்லவ ஆட்சி முடிவுக்கு வந்தது; மேலும் இவர் காவிரியின் இரு கரைகளிலும் பல கற்கோயில்களைக் கட்டினார்.","difficulty":"hard","topic":"பிற்காலச் சோழர்கள்"},{"id":143,"subject":"gk","testNumber":2,"question":"பின்வரும் சிறப்புப் பட்டங்களுள் முதலாம் இராஜராஜ சோழனுக்கு உரியவை எவை?\n1. மும்முடிச் சோழன்\n2. ஜெயங்கொண்டான்\n3. சிவபாதசேகரன்\n4. கடாரம் கொண்டான்","options":["1 மற்றும் 2 மட்டும்","1, 2 மற்றும் 4 மட்டும்","1, 2 மற்றும் 3 மட்டும்","அனைத்தும் சரி"],"correctAnswer":2,"explanation":"முதலாம் இராஜராஜ சோழன் (கி.பி. 985–1014) மும்முடிச் சோழன், ஜெயங்கொண்டான், சிவபாதசேகரன், அருண்மொழிவர்மன் போன்ற பட்டங்களைப் பெற்றிருந்தார். 'கடாரம் கொண்டான்' என்பது அவரது மகனான முதலாம் இராஜேந்திர சோழனுக்குரிய பட்டமாகும்.","difficulty":"medium","topic":"பிற்காலச் சோழர்கள்"},{"id":144,"subject":"gk","testNumber":2,"question":"முதலாம் இராஜராஜ சோழனால் கி.பி. 1010-இல் கட்டி முடிக்கப்பட்ட தஞ்சாவூர் பிரகதீஸ்வரர் கோயிலின் கருவறை விமானம் எத்தனை அடி உயரமும் எத்தனை அடுக்குகளையும் கொண்டது?","options":["216 அடி உயரம், 13 அடுக்குகள்","230 அடி உயரம், 15 அடுக்குகள்","180 அடி உயரம், 11 அடுக்குகள்","196 அடி உயரம், 12 அடுக்குகள்"],"correctAnswer":0,"explanation":"தஞ்சாவூர் பிரகதீஸ்வரர் கோயில் (இராஜராஜேஸ்வரம்) திராவிடக் கட்டிடக்கலையின் உச்சமாகக் கருதப்படுகிறது. இதன் கருவறை விமானம் 216 அடி (சுமார் 66 மீட்டர்) உயரமும் 13 அடுக்குகளையும் கொண்டுள்ளது; இதன் உச்சியில் அமைந்துள்ள சிகரம் ஒரே கல்லால் ஆன எண்கோண வடிவக் கூரையைக் கொண்டுள்ளது.","difficulty":"hard","topic":"பிற்காலச் சோழர்கள் – கட்டிடக்கலை"},{"id":145,"subject":"gk","testNumber":2,"question":"முதலாம் இராஜராஜ சோழனின் அனுமதியுடனும் கொடையுடனும் நாகப்பட்டினத்தில் 'சூடாமணி விகாரம்' என்ற பௌத்த மடாலயத்தைக் கட்டிய ஸ்ரீவிஜய (சைலேந்திர) மன்னர் யார்?","options":["மாறவிஜயோத்துங்கவர்மன்","ஐந்தாம் மகிந்தன்","சங்கராம விஜயோத்துங்கவர்மன்","விக்கிரமபாகு"],"correctAnswer":0,"explanation":"முதலாம் இராஜராஜ சோழன் தீவிர சைவப் பற்றாளராக இருந்தபோதிலும் பிற சமயங்களை மதிக்கும் சமயப் பொறை உடையவராக விளங்கினார். ஸ்ரீவிஜயத்தின் சைலேந்திர அரசரான மாறவிஜயோத்துங்கவர்மன் நாகப்பட்டினத்தில் கட்டிய சூடாமணி பௌத்த விகாரத்தின் பராமரிப்புக்காக ஆனைமங்கலம் என்ற கிராமத்தைத் தானமாக வழங்கினார் (ஆனைமங்கலம் / லெய்டன் செப்பேடு).","difficulty":"hard","topic":"பிற்காலச் சோழர்கள்"},{"id":146,"subject":"gk","testNumber":2,"question":"வடஇந்தியாவின் கங்கை நதி வரை வெற்றிகரமாகப் படையெடுத்து 'கங்கைகொண்டான்' என்றும், ஸ்ரீவிஜயத்தை வென்று 'கடாரம் கொண்டான்' என்றும் போற்றப்பட்ட சோழ மன்னர் யார்?","options":["முதலாம் இராஜேந்திர சோழன்","இராஜாதிராஜ சோழன்","வீரராஜேந்திர சோழன்","முதலாம் இராஜராஜ சோழன்"],"correctAnswer":0,"explanation":"முதலாம் இராஜேந்திர சோழன் (கி.பி. 1014–1044) வங்காளத்தின் பால வம்ச அரசர் முதலாம் மகிபாலனை வென்று கங்கை நீரைத் தமிழகத்திற்குக் கொண்டு வந்து 'கங்கைகொண்டான்' என்ற பட்டத்தைப் பெற்றார். மேலும் கி.பி. 1025-இல் வலுவான கடற்படையுடன் சென்று ஸ்ரீவிஜயப் பேரரசின் கடாரத்தை வென்று 'கடாரம் கொண்டான்' எனவும் போற்றப்பட்டார்.","difficulty":"easy","topic":"பிற்காலச் சோழர்கள்"},{"id":147,"subject":"gk","testNumber":2,"question":"முதலாம் இராஜேந்திர சோழன் தனது கங்கை வெற்றியின் நினைவாக 'நீர்மயமான வெற்றித்தூண்' (ஜலஸ்தம்பம்) என அழைக்கப்படும் எந்த ஏரியைக் கங்கைகொண்ட சோழபுரத்தில் வெட்டினார்?","options":["சோழகங்கம் ஏரி","வீராணம் ஏரி","செம்பரம்பாக்கம் ஏரி","உடையார்பாளையம் ஏரி"],"correctAnswer":0,"explanation":"முதலாம் இராஜேந்திர சோழன் கங்கைகொண்ட சோழபுரத்தைத் தனது புதிய தலைநகராக்கி அங்கு சிவன் கோயிலையும், பதினாறு மைல் நீளமுடைய 'சோழகங்கம்' (இன்றைய பொன்னேரி) என்ற பிரம்மாண்டமான நீர்ப்பாசன ஏரியையும் அமைத்தார். இதுவே 'ஜலஸ்தம்பம்' (நீர்மயமான வெற்றித்தூண்) எனத் திருவாலங்காட்டுச் செப்பேட்டில் போற்றப்படுகிறது.","difficulty":"hard","topic":"பிற்காலச் சோழர்கள்"},{"id":148,"subject":"gk","testNumber":2,"question":"முதலாம் இராஜேந்திர சோழன் வேதக் கல்லூரி ஒன்றை எங்கு நிறுவினார்?","options":["எண்ணாயிரம்","திருமுக்கூடல்","திருபுவனை","காஞ்சிபுரம்"],"correctAnswer":0,"explanation":"'பண்டித சோழன்' எனப் போற்றப்பட்ட முதலாம் இராஜேந்திர சோழன் விழுப்புரம் மாவட்டத்தில் உள்ள எண்ணாயிரம் என்ற ஊரில் மிகப்பெரிய வேதக் கல்லூரியை நிறுவினார். அங்கு 340 மாணவர்கள் தங்கிப் பயில்வதற்கும் 14 ஆசிரியர்களுக்கு ஊதியம் வழங்குவதற்கும் நிலக் கொடைகளை வழங்கினார்.","difficulty":"medium","topic":"பிற்காலச் சோழர்கள் – கல்வி"},{"id":149,"subject":"gk","testNumber":2,"question":"வணிகத்தை ஊக்குவிப்பதற்காகச் சுங்க வரிகளை நீக்கி 'சுங்கம் தவிர்த்த சோழன்' எனப் போற்றப்பட்ட சோழ மன்னர் யார்?","options":["இரண்டாம் குலோத்துங்க சோழன்","முதலாம் இராஜேந்திர சோழன்","மூன்றாம் குலோத்துங்க சோழன்","முதலாம் குலோத்துங்க சோழன்"],"correctAnswer":3,"explanation":"சாளுக்கிய-சோழ மரபைத் தோற்றுவித்த முதலாம் குலோத்துங்க சோழன் (கி.பி. 1070–1122) மக்களின் வரிச் சுமையைக் குறைத்து வணிகத்தைப் பெருக்கச் சுங்கவரிகளை ரத்து செய்தார். இதனால் இவர் 'சுங்கம் தவிர்த்த சோழன்' எனப் புகழப்பட்டார்; இவரது காலத்தில் ஜெயங்கொண்டார் 'கலிங்கத்துப்பரணி'யை இயற்றினார்.","difficulty":"easy","topic":"பிற்காலச் சோழர்கள்"},{"id":150,"subject":"gk","testNumber":2,"question":"பிற்காலச் சோழர் கால நிர்வாகப் பிரிவுகளின் சரியான இறங்கு வரிசை (பெரியதிலிருந்து சிறியது) எது?","options":["மண்டலம் → வளநாடு → நாடு → கூற்றம் / ஊர்","நாடு → மண்டலம் → வளநாடு → ஊர்","வளநாடு → மண்டலம் → கூற்றம் → நாடு","மண்டலம் → நாடு → வளநாடு → ஊர்"],"correctAnswer":0,"explanation":"சோழப் பேரரசு மிகச் சிறந்த நிர்வாக அமைப்பைக் கொண்டிருந்தது. பேரரசு பல 'மண்டலங்களாகவும்' (மாநிலங்கள்), மண்டலங்கள் 'வளநாடுகளாகவும்' (மாவட்டங்கள்), வளநாடுகள் 'நாடுகளாகவும்', நாடுகள் பல கிராமங்களைக் கொண்ட 'கூற்றம்' அல்லது 'ஊர்'களாகவும் பிரிக்கப்பட்டிருந்தன.","difficulty":"medium","topic":"பிற்காலச் சோழர்கள் – ஆட்சிமுறை"},{"id":151,"subject":"gk","testNumber":2,"question":"சோழர் கால நிலவகைகளையும் அவற்றின் பொருளையும் சரியாகப் பொருத்துக:\n1. பிரம்மதேயம் – அ. சமணப் பள்ளிகளுக்குக் கொடையளிக்கப்பட்ட நிலம்\n2. தேவதானம் – ஆ. பிராமணர்களுக்கு வரியின்றி வழங்கப்பட்ட நிலம்\n3. பள்ளிச்சந்தம் – இ. கல்வி நிலையங்களைப் பராமரிக்க வழங்கப்பட்ட நிலம்\n4. சாலபோகம் – ஈ. கோயில்களுக்குக் கொடையாக வழங்கப்பட்ட நிலம்","options":["1-அ, 2-ஈ, 3-ஆ, 4-இ","1-ஆ, 2-அ, 3-ஈ, 4-இ","1-ஈ, 2-ஆ, 3-இ, 4-அ","1-ஆ, 2-ஈ, 3-அ, 4-இ"],"correctAnswer":3,"explanation":"சோழர் காலக் கல்வெட்டுகள் பலவகை நிலக் கொடைகளைக் குறிப்பிடுகின்றன: பிரம்மதேயம் – பிராமணர்களுக்கு வழங்கப்பட்ட வரியில்லா நிலம், தேவதானம் – கோயில்களுக்கு வழங்கப்பட்ட நிலம், பள்ளிச்சந்தம் – சமண சமய நிறுவனங்களுக்கு வழங்கப்பட்ட நிலம், சாலபோகம் – கல்வி நிலையங்களின் பராமரிப்புக்காக வழங்கப்பட்ட நிலம்.","difficulty":"hard","topic":"பிற்காலச் சோழர்கள் – பொருளாதாரம்"},{"id":152,"subject":"gk","testNumber":2,"question":"பிற்காலச் சோழர் கால உலகப் புகழ்பெற்ற செப்புத் திருமேனிகள் (வெண்கலச் சிலைகள்) எந்தத் தொழில்நுட்ப முறையில் உருவாக்கப்பட்டன?","options":["சுடுமண் வார்ப்பு முறை","கண்ணாடி உருக்கல் முறை","மெழுகு இழப்பு முறை (Lost-wax casting)","கல் செதுக்கல் முறை"],"correctAnswer":2,"explanation":"சோழர் கால உலோகச் சிற்பங்கள் 'மெழுகு இழப்பு முறை' (Lost-wax casting அல்லது மதுச்சிஷ்ட விதானம்) மூலம் ஐம்பொன் மற்றும் வெண்கலத்தால் வார்க்கப்பட்டன. முதலில் மெழுகால் சிலை செய்து அதன் மீது களிமண் பூசிச் சூடாக்கி மெழுகை உருக்கி வெளியேற்றிய பின், அந்த வெற்றிடத்தில் உருகிய உலோகத்தை ஊற்றி இச்சிலைகள் வடிவமைக்கப்பட்டன.","difficulty":"medium","topic":"பிற்காலச் சோழர்கள் – கலை"},{"id":153,"subject":"gk","testNumber":2,"question":"சோழர் காலச் செப்புத் திருமேனிகளில் அண்டத்தின் படைத்தல், காத்தல், அழித்தல் ஆகிய ஐந்தொழில்களை உணர்த்துவதாக உலக அளவில் புகழ்பெற்ற வெண்கலச் சிற்பம் எது?","options":["தட்சிணாமூர்த்தி சிலை","ஆனந்தத் தாண்டவ நடராஜர் சிலை","சோமாஸ்கந்தர் சிலை","அர்த்தநாரீஸ்வரர் சிலை"],"correctAnswer":1,"explanation":"சோழர் கால வெண்கலச் சிற்பக் கலையின் சிகரமாகத் திகழ்வது 'ஆனந்தத் தாண்டவ நடராஜர்' செப்புத் திருமேனியாகும். தீச்சுடர் வட்டத்தின் (திருவாசி) நடுவே உடுக்கை, தீ, அபய முத்திரை ஆகியவற்றுடன் ஆடும் நடராஜர் வடிவம் இந்தியக் கலை மரபின் தலைசிறந்த படைப்பாகப் போற்றப்படுகிறது.","difficulty":"easy","topic":"பிற்காலச் சோழர்கள் – கலை"},{"id":154,"subject":"gk","testNumber":2,"question":"கி.பி. ஆறாம் நூற்றாண்டில் களப்பிரர்களை வீழ்த்திப் பாண்டிய அரசை மீண்டும் நிலைநாட்டியவர் யார்?","options":["அரிகேசரி மாறவர்மன்","ஸ்ரீமாறன் ஸ்ரீவல்லபன்","கடுங்கோன்","நெடுஞ்சடையன் பராந்தகன்"],"correctAnswer":2,"explanation":"பாண்டிய மன்னன் கடுங்கோன் கி.பி. ஆறாம் நூற்றாண்டின் இறுதியில் களப்பிரர்களின் ஆட்சியை முடிவுக்குக் கொண்டுவந்து பாண்டிய அரசை மீட்டெடுத்தார். இவரது சாதனையை முதலாம் வரகுணனின் (நெடுஞ்சடையன் பராந்தகன்) 'வேள்விக்குடிச் செப்பேடு' விரிவாகப் பதிவு செய்துள்ளது.","difficulty":"medium","topic":"பிற்காலப் பாண்டியர்கள்"},{"id":155,"subject":"gk","testNumber":2,"question":"இரண்டாம் பாண்டியப் பேரரசின் வலிமைமிக்க மன்னரான முதலாம் மாறவர்மன் சுந்தரபாண்டியன் யாரைத் தோற்கடித்துச் சோழ நாட்டில் வீராபிஷேகம் செய்தார்?","options":["முதலாம் இராஜேந்திர சோழன்","முதலாம் குலோத்துங்க சோழன்","இரண்டாம் இராஜராஜ சோழன்","மூன்றாம் குலோத்துங்க சோழன்"],"correctAnswer":3,"explanation":"முதலாம் மாறவர்மன் சுந்தரபாண்டியன் (கி.பி. 1216–1238) சோழ மன்னர் மூன்றாம் குலோத்துங்கனைத் தோற்கடித்துத் தஞ்சாவூர் மற்றும் உறையூரைக் கைப்பற்றி சோழ நாட்டில் வீராபிஷேகம் செய்தார். பின்னர் மூன்றாம் குலோத்துங்கன் பணிந்து வேண்டியதால் சோழ நாட்டை மீண்டும் அவரிடமே வழங்கி 'சோணாடு வழங்கியருளிய சுந்தரபாண்டியன்' எனப் பெயர் பெற்றார்.","difficulty":"hard","topic":"பிற்காலப் பாண்டியர்கள்"},{"id":156,"subject":"gk","testNumber":2,"question":"இரண்டாம் பாண்டியப் பேரரசை ஆந்திராவின் நெல்லூர் வரை விரிவுபடுத்தி 'எம்மண்டலமும் கொண்டருளிய' என்ற பட்டத்தைப் பெற்ற பாண்டிய மன்னர் யார்?","options":["மாறவர்மன் குலசேகர பாண்டியன்","முதலாம் மாறவர்மன் சுந்தரபாண்டியன்","சடையவர்மன் குலசேகரன்","முதலாம் சடையவர்மன் சுந்தரபாண்டியன்"],"correctAnswer":3,"explanation":"முதலாம் சடையவர்மன் சுந்தரபாண்டியன் (கி.பி. 1251–1268) இரண்டாம் பாண்டியப் பேரரசின் தலைசிறந்த மன்னராவார். இவர் சேரர், சோழர், ஹொய்சாளர், காக்கத்தியர் மற்றும் இலங்கை அரசர்களை வென்று நெல்லூர் வரை ஆட்சியை விரிவுபடுத்தியதோடு சிதம்பரம் மற்றும் ஸ்ரீரங்கம் கோயில்களுக்குப் பொற்கூரை வேய்ந்தார்.","difficulty":"medium","topic":"பிற்காலப் பாண்டியர்கள்"},{"id":157,"subject":"gk","testNumber":2,"question":"கி.பி. 1288 மற்றும் 1293 ஆகிய ஆண்டுகளில் பாண்டிய நாட்டின் காயல் துறைமுகத்திற்கு வருகை தந்து, பாண்டிய நாட்டை 'உலகிலேயே மிகவும் செல்வச் செழிப்பான பகுதி' என்று குறிப்பிட்ட வெனிஸ் நாட்டுப் பயணி யார்?","options":["அப்துர் ரசாக்","மார்க்கோ போலோ","நிக்கோலோ கோண்டி","இபன் பதூதா"],"correctAnswer":1,"explanation":"இத்தாலியின் வெனிஸ் நகரப் பயணியான மார்க்கோ போலோ, மாறவர்மன் குலசேகர பாண்டியனின் ஆட்சிக் காலத்தில் இருமுறை காயல் துறைமுகத்திற்கு வருகை தந்தார். பாண்டிய நாட்டின் முத்துக் குளிப்பு, குதிரை வணிகம் மற்றும் அரச செல்வ வளத்தைத் தனது பயணக் குறிப்புகளில் விரிவாகப் புகழ்ந்துள்ளார்.","difficulty":"easy","topic":"பிற்காலப் பாண்டியர்கள்"},{"id":158,"subject":"gk","testNumber":2,"question":"கி.பி. 1311-ஆம் ஆண்டில் டெல்லி சுல்தான் அலாவுதீன் கில்ஜியின் படைத்தளபதி மாலிக் கபூர் மதுரையின் மீது படையெடுக்கக் காரணமாக இருந்த வாரிசுரிமைப் போர் யாருக்கிடையே நடைபெற்றது?","options":["சுந்தரபாண்டியன் மற்றும் வீரபாண்டியன்","குலசேகரன் மற்றும் விக்ரம பாண்டியன்","மாறவர்மன் மற்றும் சடையவர்மன்","கடுங்கோன் மற்றும் மாறவர்மன்"],"correctAnswer":0,"explanation":"மாறவர்மன் குலசேகர பாண்டியனின் மகன்களான சுந்தரபாண்டியன் மற்றும் வீரபாண்டியன் ஆகியோருக்கு இடையே அரியணைக்காகக் கடுமையான வாரிசுரிமைப் போர் மூண்டது. தோல்வியடைந்த சுந்தரபாண்டியன் டெல்லி சுல்தான் அலாவுதீன் கில்ஜியின் உதவியை நாடியதால், கி.பி. 1311-இல் மாலிக் கபூர் மதுரையின் மீது படையெடுத்தார்.","difficulty":"medium","topic":"பிற்காலப் பாண்டியர்கள்"},{"id":159,"subject":"gk","testNumber":2,"question":"பிற்காலப் பாண்டியர் காலத்தில் அரேபியா மற்றும் பாரசீகத்திலிருந்து ஆண்டுக்குப் பத்தாயிரத்திற்கும் மேற்பட்ட குதிரைகள் எந்தத் துறைமுகத்தின் வழியாகப் பாண்டிய நாட்டிற்கு இறக்குமதி செய்யப்பட்டன என வாசாப் குறிப்பிடுகிறார்?","options":["பூம்புகார்","மாமல்லபுரம்","முசிறி","காயல் (காயல்பட்டினம்)"],"correctAnswer":3,"explanation":"பாரசீக வரலாற்றாசிரியரான வாசாப், மாலிக்-உல்-இஸ்லாம் ஜமாலுதீன் என்ற வணிகர் முகவர் மூலம் அரேபியா மற்றும் பாரசீகத்திலிருந்து ஆண்டுதோறும் 10,000-க்கும் மேற்பட்ட குதிரைகள் காயல் துறைமுகத்தில் இறக்குமதி செய்யப்பட்டதாகக் குறிப்பிடுகிறார். இக்குதிரை வணிகத்தில் ஈடுபட்ட உள்ளூர் வணிகர்கள் 'குதிரைச் செட்டிகள்' என அழைக்கப்பட்டனர்.","difficulty":"hard","topic":"பிற்காலப் பாண்டியர்கள்"},{"id":160,"subject":"gk","testNumber":2,"question":"கி.பி. 1529-ஆம் ஆண்டில் மதுரை நாயக்கர் வம்சத்தைத் தோற்றுவித்தவர் யார்?","options":["திருமலை நாயக்கர்","விசுவநாத நாயக்கர்","சொக்கநாத நாயக்கர்","முத்து வீரப்ப நாயக்கர்"],"correctAnswer":1,"explanation":"விஜயநகரப் பேரரசர் கிருஷ்ணதேவராயரின் பிரதிநிதியாக மதுரைக்கு அனுப்பப்பட்ட நாகம நாயக்கரின் மகனான விசுவநாத நாயக்கர் கி.பி. 1529-இல் மதுரை நாயக்கர் ஆட்சியைத் தோற்றுவித்தார். இவர் மதுரை நகரை விரிவுபடுத்திச் சிறந்த நிர்வாகத்தை ஏற்படுத்தினார்.","difficulty":"medium","topic":"மதுரை நாயக்கர்கள்"},{"id":161,"subject":"gk","testNumber":2,"question":"மதுரை நாயக்க மன்னர் விசுவநாத நாயக்கர் தனது தளவாயும் அமைச்சருமான யாருடன் இணைந்து தமிழகத்தில் 72 பாளையங்களைக் கொண்ட 'பாளையக்காரர் முறை'யை அறிமுகப்படுத்தினார்?","options":["இராமப்பையன்","அரியநாத முதலியார்","கோவிந்த தீட்சிதர்","நரசப்பையர்"],"correctAnswer":1,"explanation":"விசுவநாத நாயக்கர் தனது நம்பிக்கைக்குரிய தளவாய் மற்றும் அமைச்சரான அரியநாத முதலியாரின் உதவியுடன் தமிழகத்தில் 72 பாளையங்களை உருவாக்கிப் 'பாளையக்காரர் முறை'யை அறிமுகப்படுத்தினார். இம்முறை காவல், வரி வசூல் மற்றும் படை உதவி ஆகிய நிர்வாகப் பணிகளைத் திறம்படச் செயல்படுத்த உதவியது.","difficulty":"easy","topic":"மதுரை நாயக்கர்கள்"},{"id":162,"subject":"gk","testNumber":2,"question":"திராவிட மற்றும் இஸ்லாமியக் (இந்தோ-சாரசெனிக்) கட்டிடக்கலைப் பாணிகளின் அழகிய கலவையாக மதுரையில் 'திருமலை நாயக்கர் மகால்' என்ற அரண்மனையைக் கட்டியவர் யார்?","options":["ராணி மங்கம்மாள்","விஜயரங்க சொக்கநாதர்","விசுவநாத நாயக்கர்","திருமலை நாயக்கர்"],"correctAnswer":3,"explanation":"மதுரை நாயக்க மன்னர்களுள் தலைசிறந்தவரான திருமலை நாயக்கர் (கி.பி. 1623–1659) கி.பி. 1636-ஆம் ஆண்டில் இத்தாலியக் கட்டிடக் கலைஞரின் உதவியுடன் 'திருமலை நாயக்கர் மகால்' அரண்மனையைக் கட்டினார். மேலும் மதுரை மீனாட்சி அம்மன் கோயிலில் புதுமண்டபம், தெப்பக்குளம் ஆகியவற்றையும் அமைத்தார்.","difficulty":"easy","topic":"மதுரை நாயக்கர்கள்"},{"id":163,"subject":"gk","testNumber":2,"question":"மதுரை நாயக்க ஆட்சியில் சமயப் பொறை, சாலைகள் அமைத்தல், நிழல் தரும் மரங்கள் நடுதல் மற்றும் 'அன்னதானச் சத்திரங்கள்' அமைத்தல் ஆகிய மக்கள் நலப் பணிகளுக்காகப் புகழ்பெற்ற அரசி யார்?","options":["ராணி வேலுநாச்சியார்","செம்பியன்மாதேவி","ராணி மீனாட்சி","ராணி மங்கம்மாள்"],"correctAnswer":3,"explanation":"சொக்கநாத நாயக்கரின் மனைவியான ராணி மங்கம்மாள் (கி.பி. 1689–1706) தனது பேரன் விஜயரங்க சொக்கநாதரின் சார்பாகப் பொறுப்பேற்று 17 ஆண்டுகள் திறம்பட ஆட்சி செய்தார். கன்னியாகுமரி முதல் மதுரை வரையிலான 'மங்கம்மாள் சாலை', மதுரை மங்கம்மாள் சத்திரம், உய்யக்கொண்டான் கால்வாய் பராமரிப்பு மற்றும் அனைத்துச் சமயங்களுக்கும் வழங்கிய ஆதரவு ஆகியவை இவரது புகழை இன்றும் நிலைநிறுத்துகின்றன.","difficulty":"easy","topic":"மதுரை நாயக்கர்கள்"},{"id":164,"subject":"gk","testNumber":2,"question":"தஞ்சாவூர் நாயக்கர் வம்சத்தை கி.பி. 1532-ஆம் ஆண்டில் தோற்றுவித்தவர் யார்?","options":["அச்சுதப்ப நாயக்கர்","ரகுநாத நாயக்கர்","செவ்வப்ப நாயக்கர்","விஜயராகவ நாயக்கர்"],"correctAnswer":2,"explanation":"விஜயநகரப் பேரரசர் அச்சுததேவராயரின் காலத்தில் கி.பி. 1532-இல் செவ்வப்ப நாயக்கர் தஞ்சாவூர் நாயக்கர் ஆட்சியைத் தோற்றுவித்தார். இவர் தஞ்சாவூர் கோட்டையைப் பலப்படுத்தியதோடு சிவகங்கைக் குளத்தை வெட்டி, திருவண்ணாமலைக் கோயிலின் பெரிய கோபுரத்தையும் கட்டினார்.","difficulty":"medium","topic":"தஞ்சாவூர் நாயக்கர்கள்"},{"id":165,"subject":"gk","testNumber":2,"question":"தஞ்சாவூர் நாயக்க மன்னர்களுள் தலைசிறந்தவராக விளங்கி 'சங்கீத சுதா' என்ற இசை நூலை இயற்றி, தஞ்சாவூர் அரண்மனை நூலக வளர்ச்சிக்கு வித்திட்டவர் யார்?","options":["கிருஷ்ணப்ப நாயக்கர்","அச்சுதப்ப நாயக்கர்","ரகுநாத நாயக்கர்","செவ்வப்ப நாயக்கர்"],"correctAnswer":2,"explanation":"ரகுநாத நாயக்கர் (கி.பி. 1600–1634) தஞ்சாவூர் நாயக்க மன்னர்களுள் மிகவும் புகழ்பெற்றவர் ஆவார். வீணை வாசிப்பதில் வல்லவரான இவர் 'சங்கீத சுதா', 'பாரத சுதா' உள்ளிட்ட நூல்களை இயற்றியதோடு, தனது அமைச்சர் கோவிந்த தீட்சிதருடன் இணைந்து இசை, இலக்கியம் மற்றும் கும்பகோணம் இராமசுவாமி கோயில் ஆகியவற்றை வளர்த்தார்.","difficulty":"hard","topic":"தஞ்சாவூர் நாயக்கர்கள்"},{"id":166,"subject":"gk","testNumber":2,"question":"கி.பி. 1676-ஆம் ஆண்டில் தஞ்சாவூரில் மராத்தியர் ஆட்சியைத் தோற்றுவித்த சத்ரபதி சிவாஜியின் ஒன்றுவிட்ட சகோதரர் யார்?","options":["வெங்கோஜி (ஏகோஜி)","முதலாம் துளஜாஜி","முதலாம் சரபோஜி","அமர்சிங்"],"correctAnswer":0,"explanation":"தஞ்சாவூர் நாயக்கர் ஆட்சியின் இறுதிக் காலத்தில் ஏற்பட்ட அரசியல் குழப்பத்தைத் தொடர்ந்து, பீஜப்பூர் சுல்தானின் தளபதியாக இருந்த சத்ரபதி சிவாஜியின் ஒன்றுவிட்ட சகோதரரான வெங்கோஜி (ஏகோஜி) கி.பி. 1676-இல் தஞ்சாவூரைக் கைப்பற்றித் தஞ்சாவூர் மராத்திய வம்சத்தைத் தோற்றுவித்தார்.","difficulty":"medium","topic":"தஞ்சாவூர் மராத்தியர்கள்"},{"id":167,"subject":"gk","testNumber":2,"question":"தஞ்சாவூரில் உள்ள புகழ்பெற்ற 'சரஸ்வதி மகால் நூலகத்தை' விரிவுபடுத்தி ஆயிரக்கணக்கான அரிய ஓலைச்சுவடிகள் மற்றும் அச்சு நூல்களைச் சேகரித்து உலகப் புகழ்பெறச் செய்த மராத்திய மன்னர் யார்?","options":["வெங்கோஜி","இரண்டாம் துளஜாஜி","இரண்டாம் சரபோஜி மன்னர்","முதலாம் ஷாஜி"],"correctAnswer":2,"explanation":"இரண்டாம் சரபோஜி மன்னர் (கி.பி. 1798–1832) தஞ்சாவூர் நாயக்கர்களால் தொடங்கப்பட்ட அரண்மனை நூலகத்தை மிகப்பெரிய அளவில் விரிவுபடுத்தி 'சரஸ்வதி மகால் நூலகம்' எனப் புகழ்பெறச் செய்தார். தமிழ், சமஸ்கிருதம், மராத்தி, தெலுங்கு, ஆங்கிலம் உள்ளிட்ட பல மொழிகளின் அரிய சுவடிகள் இங்கு பாதுகாக்கப்படுகின்றன.","difficulty":"easy","topic":"தஞ்சாவூர் மராத்தியர்கள்"},{"id":168,"subject":"gk","testNumber":2,"question":"தஞ்சாவூரில் மருத்துவ ஆராய்ச்சிக்காக 'தன்வந்திரி மகால்' என்ற நிறுவனத்தையும், கண் அறுவை சிகிச்சை மற்றும் இந்திய மருத்துவ முறைகளின் ஆவணத் தொகுப்புகளையும் உருவாக்கிய மன்னர் யார்?","options":["திருமலை நாயக்கர்","ரகுநாத நாயக்கர்","முதலாம் இராஜராஜ சோழன்","இரண்டாம் சரபோஜி மன்னர்"],"correctAnswer":3,"explanation":"பன்மொழிப் புலவரும் அறிவியல் ஆர்வலருமான இரண்டாம் சரபோஜி மன்னர் தஞ்சாவூரில் 'தன்வந்திரி மகால்' என்ற மருத்துவ ஆராய்ச்சி நிறுவனத்தை நிறுவி ஆயுர்வேதம், சித்தா, யுனானி மற்றும் அலோபதி மருத்துவ முறைகளை ஆராய்ந்து 18 தொகுதிகளாக 'சரபேந்திர வைத்திய முறைகள்' எனப் பதிப்பித்தார். மேலும் தென்னிந்தியாவின் முதல் தேவநாகரி அச்சுக்கூடத்தையும் இவர் நிறுவினார்.","difficulty":"medium","topic":"தஞ்சாவூர் மராத்தியர்கள்"},{"id":169,"subject":"gk","testNumber":2,"question":"சங்க கால நகர நாகரிகத்தை வெளிப்படுத்திய புகழ்பெற்ற 'கீழடி' அகழாய்வுத் தலம் எந்த ஆற்றின் கரையில், எந்த மாவட்டத்தில் அமைந்துள்ளது?","options":["நொய்யல் ஆற்றங்கரை, ஈரோடு மாவட்டம்","வைகை ஆற்றங்கரை, சிவகங்கை மாவட்டம்","தாமிரபரணி ஆற்றங்கரை, தூத்துக்குடி மாவட்டம்","காவிரி ஆற்றங்கரை, தஞ்சாவூர் மாவட்டம்"],"correctAnswer":1,"explanation":"கீழடி அகழாய்வுத் தலம் சிவகங்கை மாவட்டத்தில் (மதுரைக்குத் தென்கிழக்கே சுமார் 12 கி.மீ. தொலைவில்) வைகை ஆற்றின் கரையில் அமைந்துள்ளது. இங்கு சுட்ட செங்கல் கட்டுமானங்கள், மூடிய கழிவுநீர்க் கால்வாய்கள், தமிழி எழுத்துப் பொறித்த பானை ஓடுகள் மற்றும் உறைகிணறுகள் கண்டெடுக்கப்பட்டுள்ளன.","difficulty":"easy","topic":"தமிழக அகழாய்வுகள் – கீழடி"},{"id":170,"subject":"gk","testNumber":2,"question":"கீழடி அகழாய்வில் கிடைத்த கரிம மாதிரிகளின் கதிரியக்கக் கார்பன் காலக் கணிப்பின்படி (AMS Dating), சங்க கால நகர நாகரிகம் எந்தக் காலத்திற்கு முற்பட்டது என அறிவியல் பூர்வமாக நிறுவப்பட்டுள்ளது?","options":["கி.பி. 1ஆம் நூற்றாண்டு","கி.மு. 3ஆம் நூற்றாண்டு","கி.மு. 6ஆம் நூற்றாண்டு (கி.மு. 580)","கி.மு. 2ஆம் நூற்றாண்டு"],"correctAnswer":2,"explanation":"அமெரிக்காவின் புளோரிடாவில் உள்ள பீட்டா அனலிட்டிக் (Beta Analytic) ஆய்வகத்தில் மேற்கொள்ளப்பட்ட கதிரியக்கக் கார்பன் சோதனையில் கீழடி நாகரிகம் கி.மு. 580-ஆம் ஆண்டைச் (கி.மு. 6ஆம் நூற்றாண்டு) சேர்ந்தது என உறுதி செய்யப்பட்டது. இதன்மூலம் கங்கைச் சமவெளி நகரமயமாக்கலுக்கு இணையான காலத்திலேயே வைகை நாகரிகமும் எழுத்தறிவுடன் செழித்திருந்தமை நிரூபிக்கப்பட்டது.","difficulty":"medium","topic":"தமிழக அகழாய்வுகள் – கீழடி"},{"id":171,"subject":"gk","testNumber":2,"question":"தூத்துக்குடி மாவட்டத்தில் தாமிரபரணி ஆற்றங்கரையில் அமைந்துள்ளதும், 1876-ஆம் ஆண்டில் ஆண்ட்ரூ ஜாகர் என்பவரால் முதன்முதலில் அகழாய்வு செய்யப்பட்டு ஏராளமான முதுமக்கள் தாழிகள் கண்டெடுக்கப்பட்டதுமான தலம் எது?","options":["அரிக்கமேடு","பொருந்தல்","கொடுமணல்","ஆதிச்சநல்லூர்"],"correctAnswer":3,"explanation":"ஆதிச்சநல்லூர் தூத்துக்குடி மாவட்டத்தில் தாமிரபரணி ஆற்றங்கரையில் அமைந்துள்ள புகழ்பெற்ற இரும்புக்காலப் புதைவிடத் தலமாகும். 1876-இல் ஜெர்மனி நாட்டைச் சேர்ந்த டாக்டர் ஆண்ட்ரூ ஜாகர் முதன்முதலில் இங்கு அகழாய்வு செய்தார்; இங்கு முதுமக்கள் தாழிகள், இரும்பு ஆயுதங்கள், வெண்கலப் பொருட்கள் மற்றும் தங்க நெற்றிப்பட்டங்கள் கண்டெடுக்கப்பட்டுள்ளன.","difficulty":"easy","topic":"தமிழக அகழாய்வுகள் – ஆதிச்சநல்லூர்"},{"id":172,"subject":"gk","testNumber":2,"question":"சங்க இலக்கியமான 'பதிற்றுப்பத்து' நூலில் குறிப்பிடப்படும் வணிக மற்றும் தொழில்துறை நகரமான 'கொடுமணல்' எந்த மாவட்டத்தில் அமைந்துள்ளது?","options":["கோயம்புத்தூர் மாவட்டம்","ஈரோடு மாவட்டம்","திருப்பூர் மாவட்டம்","கரூர் மாவட்டம்"],"correctAnswer":1,"explanation":"கொடுமணல் ஈரோடு மாவட்டத்தில் நொய்யல் ஆற்றின் வடகரையில் அமைந்துள்ளது. சங்க இலக்கியமான பதிற்றுப்பத்து இந்நகரைச் சேரர்களின் விலைமதிப்பற்ற கற்கள் மற்றும் அணிகலன்கள் தயாரிக்கும் 'கொடுமணம்' எனப் போற்றுகிறது.","difficulty":"easy","topic":"தமிழக அகழாய்வுகள் – கொடுமணல்"},{"id":173,"subject":"gk","testNumber":2,"question":"கொடுமணல் அகழாய்வில் கண்டறியப்பட்ட முக்கியத் தொல்லியல் சான்றுகள் எவை?\n1. தமிழ்-பிராமி (தமிழி) எழுத்துப் பொறித்த பானை ஓடுகள்\n2. சூதுபவள மணிகள் மற்றும் குவார்ட்ஸ் மணிகள்\n3. இரும்பு உருக்கும் உலைகள் மற்றும் சுழல் அச்சுகள்\n4. ரோமானிய அகஸ்டஸ் கோயில் எச்சங்கள்","options":["1 மற்றும் 4 மட்டும்","2 மற்றும் 3 மட்டும்","1, 2 மற்றும் 3 மட்டும்","அனைத்தும் சரி"],"correctAnswer":2,"explanation":"கொடுமணல் அகழாய்வில் நூற்றுக்கணக்கான தமிழ்-பிராமி எழுத்துப் பொறித்த பானை ஓடுகள், சூதுபவள மற்றும் மணிக்கல் தயாரிப்புக் கூடங்கள், இரும்பு உருக்கும் உலைகள், நூல் நூற்கும் சுழல் அச்சுகள் மற்றும் பெருங்கற்கால ஈமச்சின்னங்கள் கண்டறியப்பட்டுள்ளன. அகஸ்டஸ் கோயில் முசிறியுடன் தொடர்புடையது.","difficulty":"hard","topic":"தமிழக அகழாய்வுகள் – கொடுமணல்"},{"id":174,"subject":"gk","testNumber":2,"question":"புதுச்சேரி அருகே அமைந்துள்ள 'அரிக்கமேடு' தொல்லியல் தளத்தில் 1945-ஆம் ஆண்டில் அறிவியல் பூர்வமான அகழாய்வை மேற்கொண்டு ரோமானிய வணிகத் தொடர்பை உறுதிப்படுத்தியவர் யார்?","options":["ராபர்ட் புரூஸ் பூட்","சர் மார்டிமர் வீலர்","ஜான் மார்ஷல்","அலெக்சாண்டர் ரீ"],"correctAnswer":1,"explanation":"புதுச்சேரிக்கு அருகே அரியாங்குப்பம் ஆற்றங்கரையில் அமைந்துள்ள அரிக்கமேடு 'பெரிப்ளஸ்' நூலில் 'பொதுகே' எனக் குறிப்பிடப்பட்டுள்ளது. 1945-இல் சர் மார்டிமர் வீலர் இங்கு அறிவியல் பூர்வமாக அகழாய்வு செய்து ரோமானிய அரிட்டைன் மட்பாண்டங்கள், ஆம்போரா மது ஜாடிகள் மற்றும் சாயத் தொட்டிகளைக் கண்டறிந்தார்.","difficulty":"medium","topic":"தமிழக அகழாய்வுகள் – அரிக்கமேடு"},{"id":175,"subject":"gk","testNumber":2,"question":"தூத்துக்குடி மாவட்டம் 'சிவகளை' அகழாய்வில் முதுமக்கள் தாழிக்குள் கண்டெடுக்கப்பட்ட நெல் மணிகளின் காலம் எவ்வளவு பழமையானது என அமெரிக்காவின் பீட்டா அனலிட்டிக் ஆய்வகம் உறுதிப்படுத்தியுள்ளது?","options":["கி.மு. 580 (சுமார் 2,600 ஆண்டுகள் பழமையானது)","கி.மு. 1155 (சுமார் 3,200 ஆண்டுகள் பழமையானது)","கி.பி. 100 (சுமார் 1,900 ஆண்டுகள் பழமையானது)","கி.மு. 300 (சுமார் 2,300 ஆண்டுகள் பழமையானது)"],"correctAnswer":1,"explanation":"தூத்துக்குடி மாவட்டம் சிவகளை அகழாய்வில் முதுமக்கள் தாழியிலிருந்து எடுக்கப்பட்ட உமியுடன் கூடிய நெல் மணிகளை அமெரிக்காவின் பீட்டா அனலிட்டிக் ஆய்வகத்தில் ஆய்வு செய்ததில் அதன் காலம் கி.மு. 1155 என உறுதிப்படுத்தப்பட்டது. இது தாமிரபரணி (பொருநை) ஆற்றங்கரை நாகரிகம் 3,200 ஆண்டுகள் பழமையானது என்பதை நிரூபித்தது.","difficulty":"medium","topic":"தமிழக அகழாய்வுகள் – சிவகளை"},{"id":176,"subject":"gk","testNumber":2,"question":"பழனி அருகே அமைந்துள்ளதும், நெல் மணிகள் அடங்கிய பானை, கண்ணாடி மணிகள், இரும்பு வாள் மற்றும் தமிழ்-பிராமி எழுத்துப் பொறித்த பானை ஓடு ஆகியவை கண்டெடுக்கப்பட்டதுமான அகழாய்வுத் தலம் எது?","options":["பட்டறைப்பெரும்புதூர்","வெம்பக்கோட்டை","பொருந்தல் (திண்டுக்கல் மாவட்டம்)","துலுக்கர்பட்டி"],"correctAnswer":2,"explanation":"திண்டுக்கல் மாவட்டம் பழனிக்கு அருகே அமைந்துள்ள பொருந்தல் அகழாய்வில் (பேராசிரியர் கே. ராஜன் தலைமையில்) பெருங்கற்கால ஈமப்பேழைக்குள் நெல் மணிகள் நிரப்பப்பட்ட பானை, கண்ணாடி மணிகள், இரும்பு வாள் மற்றும் 'வயிரா' என்ற தமிழ்-பிராமி எழுத்துப் பொறித்த பானை ஓடு ஆகியவை கண்டறியப்பட்டன.","difficulty":"medium","topic":"தமிழக அகழாய்வுகள் – பொருந்தல்"},{"id":177,"subject":"gk","testNumber":2,"question":"தமிழ்நாட்டில் இரும்பு பயன்படுத்தப்பட்ட காலம் கி.மு. 2172 (சுமார் 4,200 ஆண்டுகள் பழமையானது) என அறிவியல் ஆய்வுகளின் மூலம் உறுதிப்படுத்தப்பட்ட அகழாய்வுத் தலம் எது?","options":["அழகன்குளம் (இராமநாதபுரம்)","கொற்கை (தூத்துக்குடி)","கீழடி (சிவகங்கை)","மயிலாடும்பாறை (கிருஷ்ணகிரி)"],"correctAnswer":3,"explanation":"கிருஷ்ணகிரி மாவட்டத்தில் உள்ள மயிலாடும்பாறை அகழாய்வில் கிடைத்த இரும்புப் பொருட்களின் காலக்கணிப்பில் தமிழகத்தில் இரும்புப் பயன்பாடு கி.மு. 2172-க்கும் முற்பட்டது (4,200 ஆண்டுகள் பழமையானது) என உறுதி செய்யப்பட்டது. மேலும் இங்கு புதிய கற்காலம் முதல் இரும்புக்காலம் வரையிலான பண்பாட்டு அடுக்குகள் கிடைத்துள்ளன.","difficulty":"medium","topic":"தமிழக அகழாய்வுகள் – மயிலாடும்பாறை"},{"id":178,"subject":"gk","testNumber":2,"question":"முதலாம் இராஜேந்திர சோழனின் செங்கல் அரண்மனை எச்சங்கள் கண்டறியப்பட்டுள்ள 'மாளிகைமேடு' அகழாய்வுத் தலம் எந்த மாவட்டத்தில் அமைந்துள்ளது?","options":["திருவாரூர் மாவட்டம்","நாகப்பட்டினம் மாவட்டம்","அரியலூர் மாவட்டம் (கங்கைகொண்ட சோழபுரம்)","தஞ்சாவூர் மாவட்டம்"],"correctAnswer":2,"explanation":"அரியலூர் மாவட்டத்தில் அமைந்துள்ள கங்கைகொண்ட சோழபுரத்திற்கு அருகிலுள்ள 'மாளிகைமேடு' அகழாய்வில் முதலாம் இராஜேந்திர சோழனின் அரண்மனைச் சுவர்கள், சுட்ட செங்கல் கட்டுமானங்கள், சீன போர்சலின் மட்பாண்ட ஓடுகள் மற்றும் இரும்பு ஆணிகள் கண்டறியப்பட்டுள்ளன.","difficulty":"medium","topic":"தமிழக அகழாய்வுகள் – கங்கைகொண்ட சோழபுரம்"},{"id":179,"subject":"gk","testNumber":2,"question":"பாண்டியன் நெடுஞ்செழியனின் பணியாளரான கடலன் வழுதி சமணத் துறவி கணிய நந்தாசிரியருக்குக் கற்படுக்கை அமைத்துக் கொடுத்ததைக் குறிப்பிடும் கி.மு. 2ஆம் நூற்றாண்டுத் தமிழ்-பிராமி கல்வெட்டு எங்குள்ளது?","options":["மாங்குளம் (மதுரை மாவட்டம்)","சித்தன்னவாசல் (புதுக்கோட்டை மாவட்டம்)","ஜம்பை (விழுப்புரம் மாவட்டம்)","புகளூர் (கரூர் மாவட்டம்)"],"correctAnswer":0,"explanation":"மதுரை மாவட்டத்தில் உள்ள மாங்குளம் (மீனாட்சிபுரம்) குகைக் கல்வெட்டுகள் கி.மு. 2ஆம் நூற்றாண்டைச் சேர்ந்த பழமையான தமிழ்-பிராமி (தமிழி) கல்வெட்டுகளாகும். இவை பாண்டியன் நெடுஞ்செழியன் மற்றும் சமணத் துறவி கணிய நந்தாசிரியர் ஆகியோரின் வரலாற்றுத் தொன்மையை உறுதிப்படுத்துகின்றன.","difficulty":"hard","topic":"தமிழ்-பிராமி கல்வெட்டுகள்"},{"id":180,"subject":"gk","testNumber":2,"question":"ஆதன் செல் இரும்பொறை, பெருங்கடுங்கோ, இளங்கடுங்கோ ஆகிய மூன்று தலைமுறைச் சேர மன்னர்களின் பெயர்களைக் குறிப்பிடும் தமிழ்-பிராமி கல்வெட்டு எங்கு அமைந்துள்ளது?","options":["எடக்கல்","மாங்குளம்","அழகர்மலை","புகளூர் (கரூர் மாவட்டம்)"],"correctAnswer":3,"explanation":"கரூர் மாவட்டத்தில் உள்ள புகளூர் ஆறுநாட்டார் மலையில் காணப்படும் தமிழ்-பிராமி கல்வெட்டு சமணத் துறவி செங்காயபனுக்குக் கற்படுக்கை அமைத்துத் தந்ததைக் குறிப்பிடுகிறது. இதில் சங்க இலக்கியமான பதிற்றுப்பத்தில் இடம்பெறும் மூன்று தலைமுறைச் சேர மன்னர்களின் பெயர்கள் வரிசையாகப் பொறிக்கப்பட்டுள்ளன.","difficulty":"hard","topic":"தமிழ்-பிராமி கல்வெட்டுகள்"},{"id":181,"subject":"gk","testNumber":2,"question":"களப்பிரர் கால மன்னன் 'கோச்சேந்தன் கூற்றன்' பற்றியும், தமிழ்-பிராமி எழுத்துக்கள் வட்டெழுத்தாக மாற்றமடைந்த நிலையையும் குறிப்பிடும் கி.பி. 5ஆம் நூற்றாண்டுக் கல்வெட்டு எது?","options":["மண்டகப்பட்டுக் கல்வெட்டு","உத்திரமேரூர் கல்வெட்டு","மாங்குளம் கல்வெட்டு","பூலாங்குறிச்சி கல்வெட்டு (சிவகங்கை மாவட்டம்)"],"correctAnswer":3,"explanation":"சிவகங்கை மாவட்டத்தில் உள்ள பூலாங்குறிச்சி கல்வெட்டு கி.பி. 5ஆம் நூற்றாண்டைச் சேர்ந்த மிக முக்கியமான தொல்லியல் ஆவணமாகும். இதில் 'கோச்சேந்தன் கூற்றன்' என்ற களப்பிர மன்னனின் ஆட்சியாண்டும், அக்கால ஆட்சிப் பிரிவுகள் மற்றும் வட்டெழுத்து வளர்ச்சியின் தொடக்க நிலையும் இடம்பெற்றுள்ளன.","difficulty":"hard","topic":"தமிழகத் தொல்லியல் கல்வெட்டுகள்"},{"id":182,"subject":"gk","testNumber":2,"question":"சமணத் துறவி சந்திரநந்தி 57 நாட்கள் உண்ணாவிரதம் இருந்து உயிர் நீத்ததை (வடக்கிருத்தல் / நிஷிதிகை) குறிப்பிடும் பழமையான வட்டெழுத்துக் கல்வெட்டு எங்குள்ளது?","options":["ஆனைமலை","புகளூர்","திருநாதர்குன்று (விழுப்புரம் மாவட்டம்)","கழுகுமலை"],"correctAnswer":2,"explanation":"விழுப்புரம் மாவட்டம் செஞ்சிக்கு அருகே அமைந்துள்ள திருநாதர்குன்று பாறையில் காணப்படும் கி.பி. 5–6ஆம் நூற்றாண்டு வட்டெழுத்துக் கல்வெட்டு, சமணத் துறவி சந்திரநந்தி ஆசிரியர் 57 நாட்கள் உண்ணாநோன்பு (வடக்கிருத்தல்) இருந்து உயிர் நீத்த செய்தியைப் பதிவு செய்துள்ளது.","difficulty":"hard","topic":"தமிழகத் தொல்லியல் கல்வெட்டுகள்"},{"id":183,"subject":"gk","testNumber":2,"question":"இந்தியக் கோயில் கட்டிடக்கலையின் மூன்று முக்கியப் பாணிகளையும் அவை செழித்த பகுதிகளையும் சரியாகப் பொருத்துக:\n1. நாகர பாணி – அ. தென்னிந்தியா\n2. திராவிட பாணி – ஆ. வடஇந்தியா\n3. வேசர பாணி – இ. தக்காணம் (கலப்புப் பாணி)","options":["1-இ, 2-அ, 3-ஆ","1-ஆ, 2-இ, 3-அ","1-அ, 2-ஆ, 3-இ","1-ஆ, 2-அ, 3-இ"],"correctAnswer":3,"explanation":"இந்தியக் கோயில் கட்டிடக்கலை மூன்று பெரும் பாணிகளைக் கொண்டது: இமயமலைக்கும் விந்திய மலைக்கும் இடைப்பட்ட வடஇந்தியாவில் 'நாகர பாணி', கிருஷ்ணா நதிக்கும் கன்னியாகுமரிக்கும் இடைப்பட்ட தென்னிந்தியாவில் 'திராவிட பாணி', விந்திய மலைக்கும் கிருஷ்ணா நதிக்கும் இடைப்பட்ட தக்காணப் பகுதியில் இரண்டின் கலப்பான 'வேசர பாணி' ஆகியவை வளர்ந்தன.","difficulty":"easy","topic":"இந்தியக் கோயில் கட்டிடக்கலை"},{"id":184,"subject":"gk","testNumber":2,"question":"திராவிடக் கோயில் கட்டிடக்கலையில் கருவறையின் (கர்ப்பக்கிரகம்) மீது பிரமிடு வடிவில் அடுக்குகளாகக் கட்டப்படும் உயர்ந்த அமைப்பு எவ்வாறு அழைக்கப்படுகிறது?","options":["பிரகாரம்","விமானம்","கோபுரம்","அர்த்தமண்டபம்"],"correctAnswer":1,"explanation":"திராவிடக் கோயில் கட்டிடக்கலையில் மூலவர் வீற்றிருக்கும் கருவறையின் (கர்ப்பக்கிரகம்) மீது பிரமிடு வடிவில் படிப்படியாகக் குறுகிச் செல்லும் அடுக்குகளாகக் கட்டப்படும் அமைப்பு 'விமானம்' எனப்படும். கோயிலின் வெளிச்சுற்று நுழைவாயில்களின் மீது கட்டப்படும் உயர்ந்த கோபுர அமைப்பு 'கோபுரம்' என அழைக்கப்படுகிறது.","difficulty":"easy","topic":"திராவிடக் கோயில் கட்டிடக்கலை"},{"id":185,"subject":"gk","testNumber":2,"question":"பல்லவர் காலச் சிற்பக் கலைக்குச் சான்றாகத் திகழும் மாமல்லபுரம் நினைவுச்சின்னங்கள் எந்த ஆண்டு யுனெஸ்கோ (UNESCO) உலகப் பாரம்பரியத் தலமாக அறிவிக்கப்பட்டன?","options":["1980","2004","1987","1984"],"correctAnswer":3,"explanation":"மாமல்லபுரத்தில் அமைந்துள்ள பஞ்ச பாண்டவர் ரதங்கள், அர்ச்சுனன் தபசு (பகீரதன் தவம்) புடைப்புச் சிற்பம், கடற்கரைக் கோயில் மற்றும் குடைவரை மண்டபங்கள் உள்ளிட்ட நினைவுச்சின்னத் தொகுதி 1984-ஆம் ஆண்டில் யுனெஸ்கோ (UNESCO) உலகப் பாரம்பரியத் தலமாக அங்கீகரிக்கப்பட்டது.","difficulty":"medium","topic":"யுனெஸ்கோ பாரம்பரியத் தலங்கள்"},{"id":186,"subject":"gk","testNumber":2,"question":"யுனெஸ்கோவின் 'அழியாத சோழர் பெருங்கோயில்கள்' (Great Living Chola Temples) என்ற உலகப் பாரம்பரியப் பட்டியலில் இடம்பெற்றுள்ள மூன்று கோயில்கள் எவை?","options":["தஞ்சாவூர் பிரகதீஸ்வரர், சிதம்பரம் நடராஜர், மதுரை மீனாட்சி அம்மன் கோயில்கள்","தஞ்சாவூர் பிரகதீஸ்வரர், காஞ்சி கைலாசநாதர், ஸ்ரீரங்கம் ரங்கநாதர் கோயில்கள்","கங்கைகொண்ட சோழபுரம், திருவாரூர் தியாகராஜர், கும்பகோணம் சாரங்கபாணி கோயில்கள்","தஞ்சாவூர் பிரகதீஸ்வரர், கங்கைகொண்ட சோழபுரம் பிரகதீஸ்வரர், தாராசுரம் ஐராவதீஸ்வரர் கோயில்கள்"],"correctAnswer":3,"explanation":"யுனெஸ்கோ உலகப் பாரம்பரியப் பட்டியலில் தஞ்சாவூர் பிரகதீஸ்வரர் கோயில் 1987-ஆம் ஆண்டிலும், கங்கைகொண்ட சோழபுரம் பிரகதீஸ்வரர் கோயில் மற்றும் தாராசுரம் ஐராவதீஸ்வரர் கோயில் ஆகிய இரண்டும் 2004-ஆம் ஆண்டிலும் இணைக்கப்பட்டு 'அழியாத சோழர் பெருங்கோயில்கள்' என அழைக்கப்படுகின்றன.","difficulty":"easy","topic":"யுனெஸ்கோ பாரம்பரியத் தலங்கள்"},{"id":187,"subject":"gk","testNumber":2,"question":"கும்பகோணத்திற்கு அருகிலுள்ள 'தாராசுரம் ஐராவதீஸ்வரர் கோயிலை'க் கட்டிய சோழ மன்னர் யார்?","options":["மூன்றாம் குலோத்துங்க சோழன்","இரண்டாம் இராஜராஜ சோழன்","முதலாம் இராஜேந்திர சோழன்","முதலாம் இராஜராஜ சோழன்"],"correctAnswer":1,"explanation":"யுனெஸ்கோ பாரம்பரியத் தலமான தாராசுரம் ஐராவதீஸ்வரர் கோயில் கி.பி. 12ஆம் நூற்றாண்டில் இரண்டாம் இராஜராஜ சோழனால் கட்டப்பட்டது. குதிரைகள் பூட்டிய கல் தேர் வடிவிலான முன்மண்டபம், நுண்ணிய சிற்ப வேலைப்பாடுகள் மற்றும் இசை எழுப்பும் படிக்கட்டுகள் இக்கோயிலின் தனிச்சிறப்புகளாகும்.","difficulty":"medium","topic":"கோயில் கட்டிடக்கலை"},{"id":188,"subject":"gk","testNumber":2,"question":"தமிழகத்தின் செவ்வியல் நடனமான பரதநாட்டியத்தின் இலக்கணத்திற்கு அடிப்படையாக விளங்கும் 'நாட்டிய சாஸ்திரம்' என்ற நூலை இயற்றியவர் யார்?","options":["சாரங்கதேவர்","பரத முனிவர்","அபிநவகுப்தர்","நந்திகேஸ்வரர்"],"correctAnswer":1,"explanation":"பரத முனிவரால் இயற்றப்பட்ட 'நாட்டிய சாஸ்திரம்' இந்தியச் செவ்வியல் நடனம், நாடகம் மற்றும் இசைக்கான மிகப் பழமையான இலக்கண நூலாகும். தமிழகத்தில் தொல்காப்பியம், சிலப்பதிகாரம் (அரங்கேற்று காதை) ஆகிய நூல்களும் கூத்து மற்றும் ஆடல் கலைகளின் வளமான மரபைப் பதிவு செய்துள்ளன.","difficulty":"easy","topic":"தமிழகக் கலைகள் – பரதநாட்டியம்"},{"id":189,"subject":"gk","testNumber":2,"question":"சின்னையா, பொன்னையா, சிவானந்தம், வடிவேலு ஆகிய 'தஞ்சாவூர் நால்வர்' (Tanjore Quartet) எந்தக் கலையை அலாரிப்பு முதல் தில்லானா வரையிலான இன்றைய மேடை வடிவத்திற்கு நெறிப்படுத்தினர்?","options":["பரதநாட்டியம்","தெருக்கூத்து","கரகாட்டம்","பொம்மலாட்டம்"],"correctAnswer":0,"explanation":"தஞ்சாவூர் மராத்திய மன்னர் இரண்டாம் சரபோஜி காலத்தில் வாழ்ந்த சின்னையா, பொன்னையா, சிவானந்தம், வடிவேலு ஆகிய 'தஞ்சாவூர் நால்வர்' சதிர் எனப்பட்ட பரதநாட்டியத்திற்கு அலாரிப்பு, ஜதீஸ்வரம், சப்தம், வர்ணம், பதம், தில்லானா என்ற ஒழுங்குபடுத்தப்பட்ட மேடை வடிவத்தை (மார்க்கம்) உருவாக்கினர்.","difficulty":"medium","topic":"தமிழகக் கலைகள் – பரதநாட்டியம்"},{"id":190,"subject":"gk","testNumber":2,"question":"திருவாரூரில் பிறந்தவரும் 'கர்நாடக இசை மும்மூர்த்திகள்' (Trinity of Carnatic Music) எனப் போற்றப்படுபவர்களுமான மூவர் யாவர்?","options":["முத்துத்தாண்டவர், அருணாசலக் கவிராயர், மாரிமுத்தா பிள்ளை","புரந்தரதாசர், அன்னமாச்சாரியார், தியாகராஜர்","தியாகராஜர், முத்துசுவாமி தீட்சிதர், சியாமா சாஸ்திரி","பாபநாசம் சிவன், ஊத்துக்காடு வெங்கடகவி, கோபாலகிருஷ்ண பாரதியார்"],"correctAnswer":2,"explanation":"தியாகராஜர், முத்துசுவாமி தீட்சிதர் மற்றும் சியாமா சாஸ்திரி ஆகிய மூவரும் 'கர்நாடக இசை மும்மூர்த்திகள்' எனப் போற்றப்படுகின்றனர். இம்மூவரும் தமிழ்நாட்டின் திருவாரூரில் பிறந்து கர்நாடக இசைக்குப் பல ஆயிரக்கணக்கான கீர்த்தனைகளைப் படைத்து வளப்படுத்தியவர்கள் ஆவர்.","difficulty":"easy","topic":"கர்நாடக இசை"},{"id":191,"subject":"gk","testNumber":2,"question":"பண்டையத் தமிழிசையில் 'பண்' என்பது இன்றைய கர்நாடக இசையின் எதற்கு இணையானது?","options":["தாளம்","இராகம்","காலப்பிரமாணம்","சுருதி"],"correctAnswer":1,"explanation":"பண்டையத் தமிழிசையில் 'பண்' என்பது இன்றைய கர்நாடக இசையின் 'இராகம்' என்பதற்கு இணையானதாகும். பண்டையத் தமிழர்கள் ஏழு சுரங்களைக் குரல், துத்தம், கைக்கிளை, உழை, இளி, விளரி, தாரம் என அழைத்து, 103 பண்களை உருவாக்கிப் பண்ணொடு தேவாரப் பாடல்களைப் பாடினர்.","difficulty":"medium","topic":"தமிழிசை"},{"id":192,"subject":"gk","testNumber":2,"question":"'தமிழிசை மும்மூர்த்திகள்' (ஆதி மும்மூர்த்திகள்) எனப் போற்றப்படும் சீர்காழி இசை அறிஞர்கள் மூவர் யாவர்?","options":["இளங்கோவடிகள், திருவள்ளுவர், கம்பர்","முத்துத்தாண்டவர், அருணாசலக் கவிராயர், மாரிமுத்தா பிள்ளை","அப்பர், சம்பந்தர், சுந்தரர்","தியாகராஜர், முத்துசுவாமி தீட்சிதர், சியாமா சாஸ்திரி"],"correctAnswer":1,"explanation":"சீர்காழியைச் சேர்ந்த முத்துத்தாண்டவர், அருணாசலக் கவிராயர் மற்றும் மாரிமுத்தா பிள்ளை ஆகிய மூவரும் 'தமிழிசை மும்மூர்த்திகள்' எனப் போற்றப்படுகின்றனர். இவர்கள் கர்நாடக இசை மும்மூர்த்திகளுக்கும் முந்தைய காலத்திலேயே பல்லவி, அனுபல்லவி, சரணம் என்ற கீர்த்தனை வடிவத்தில் தமிழிசைப் பாடல்களை இயற்றினர்.","difficulty":"medium","topic":"தமிழிசை"},{"id":193,"subject":"gk","testNumber":2,"question":"தமிழர்களின் அறுவடைத் திருநாளான பொங்கல் விழா நான்கு நாட்கள் கொண்டாடப்படுகிறது; அதன் சரியான வரிசை எது?","options":["போகிப் பொங்கல், தைப்பொங்கல், காணும் பொங்கல், மாட்டுப் பொங்கல்","போகிப் பொங்கல், மாட்டுப் பொங்கல், தைப்பொங்கல், காணும் பொங்கல்","போகிப் பொங்கல், தைப்பொங்கல், மாட்டுப் பொங்கல், காணும் பொங்கல்","தைப்பொங்கல், போகிப் பொங்கல், மாட்டுப் பொங்கல், காணும் பொங்கல்"],"correctAnswer":2,"explanation":"தமிழர்களின் தனிப்பெரும் அறுவடைத் திருநாளான பொங்கல் மார்கழி இறுதி நாள் தொடங்கி தை மூன்றாம் நாள் வரை நான்கு நாட்கள் கொண்டாடப்படுகிறது: 1. போகிப் பொங்கல் (பழையன கழிதலும் புதியன புகுதலும்), 2. தைப்பொங்கல் (சூரிய வழிபாடு), 3. மாட்டுப் பொங்கல் (உழவுக்கு உதவும் கால்நடைகளுக்கு நன்றி), 4. காணும் பொங்கல் (உறவுகளையும் பெரியோரையும் சந்தித்தல்).","difficulty":"easy","topic":"தமிழக விழாக்கள் & பண்பாடு"},{"id":194,"subject":"gk","testNumber":2,"question":"தமிழகத்தின் பாரம்பரிய வீர விளையாட்டான 'ஜல்லிக்கட்டு' (மஞ்சுவிரட்டு) எந்தச் சங்க இலக்கிய நூலில் 'ஏறுதழுவுதல்' என விரிவாக வருணிக்கப்பட்டுள்ளது?","options":["நற்றிணை","குறுந்தொகை","ஐங்குறுநூறு","கலித்தொகை (முல்லைக்கலி)"],"correctAnswer":3,"explanation":"சங்க இலக்கியமான கலித்தொகையின் முல்லைக்கலிப் பாடல்களில் ஆயர் குல வீரர்கள் சீறி வரும் காளைகளை அடக்கும் 'ஏறுதழுவுதல்' விளையாட்டு விரிவாகப் பாடப்பட்டுள்ளது. இதுவே இன்றும் பொங்கல் விழாவின்போது அலங்காநல்லூர், பாலமேடு, அவனியாபுரம் ஆகிய இடங்களில் ஜல்லிக்கட்டாகக் கொண்டாடப்படுகிறது.","difficulty":"easy","topic":"தமிழக விழாக்கள் & பண்பாடு"},{"id":195,"subject":"gk","testNumber":2,"question":"புதுக்கோட்டை மாவட்டத்தில் அமைந்துள்ள 'சித்தன்னவாசல்' குகை ஓவியங்கள் குறித்த பின்வரும் கூற்றுகளில் சரியானது எது?\n1. இவை சமண சமயத்தைச் சேர்ந்த இயற்கை வண்ணச் சுவரோவியங்கள் ஆகும்.\n2. அஜந்தா ஓவியங்களுக்கு இணையான 'தாமரைக் குளம்' ஓவியம் இங்குள்ளது.\n3. பாண்டிய மன்னர் ஸ்ரீமாறன் ஸ்ரீவல்லபன் காலத்தில் மதுரை ஆசிரியர் இளங்கௌதமன் இவற்றைப் புதுப்பித்தார்.","options":["1, 2 மற்றும் 3 அனைத்தும் சரி","1 மற்றும் 2 மட்டும் சரி","2 மற்றும் 3 மட்டும் சரி","1 மட்டும் சரி"],"correctAnswer":0,"explanation":"புதுக்கோட்டை மாவட்டத்தில் உள்ள சித்தன்னவாசல் (அறிவர் கோயில்) குடைவரைக் கோயில் ஓவியங்கள் சமண சமய மரபைச் சேர்ந்தவை. இங்குள்ள தாமரைக் குளம், நடனமாதர் மற்றும் அரசன்-அரசி ஓவியங்கள் அஜந்தா ஓவியங்களுக்கு இணையானவை; 9ஆம் நூற்றாண்டுப் பாண்டிய மன்னர் ஸ்ரீமாறன் ஸ்ரீவல்லபன் காலத்தில் இளங்கௌதமன் இதனைப் புதுப்பித்ததாகக் கல்வெட்டு கூறுகிறது.","difficulty":"medium","topic":"தமிழக ஓவியக்கலை – சித்தன்னவாசல்"},{"id":196,"subject":"gk","testNumber":2,"question":"புவிசார் குறியீடு (GI Tag) பெற்ற 'தஞ்சாவூர் ஓவியங்களின்' (Tanjore Paintings) தனித்துவமான சிறப்பம்சம் எது?","options":["பனை ஓலைகளில் மட்டும் கரிப்பொடியால் வரையப்படுவது","தங்கத் தகடுகள் மற்றும் வண்ணக் கற்கள் பதித்துப் புடைப்புத் தோற்றம் அளிப்பது","வெள்ளைத் துணியில் இயற்கை நீலச்சாயம் மட்டும் பயன்படுத்துவது","கண்ணாடிப் பலகைகளில் நீர்வண்ணம் மட்டுமே பயன்படுத்துவது"],"correctAnswer":1,"explanation":"தஞ்சாவூர் நாயக்கர் மற்றும் மராத்தியர் காலத்தில் செழித்து வளர்ந்த தஞ்சாவூர் ஓவியங்கள் பலா மரப் பலகையின் மீது துணி ஒட்டி, சுண்ணாம்புக் கலவையால் புடைப்புத் தோற்றம் (Embossing) உருவாக்கி, தூய தங்கத் தகடுகள் (Gold foil) மற்றும் வண்ணக் கற்கள் பதித்து வரைவதால் தனித்துவமான பொலிவுடன் விளங்குகின்றன.","difficulty":"easy","topic":"தமிழக ஓவியக்கலை – தஞ்சாவூர் ஓவியம்"},{"id":197,"subject":"gk","testNumber":2,"question":"ராஜகிரி, கிருஷ்ணகிரி, சந்திரகிரி ஆகிய மூன்று மலைகளை உள்ளடக்கியதும், ஆங்கிலேயர்களால் 'கிழக்கின் டிராய்' (Troy of the East) எனப் புகழப்பட்டதுமான தமிழகக் கோட்டை எது?","options":["செஞ்சிக் கோட்டை","ஆலம்பரை கோட்டை","திண்டுக்கல் கோட்டை","வேலூர் கோட்டை"],"correctAnswer":0,"explanation":"விழுப்புரம் மாவட்டத்தில் அமைந்துள்ள செஞ்சிக் கோட்டை ராஜகிரி, கிருஷ்ணகிரி, சந்திரகிரி ஆகிய மூன்று மலைகளை இணைத்து மிக வலிமையாகக் கட்டப்பட்டுள்ளது. இக்கோட்டையின் அரண்களைக் கண்டு வியந்த சத்ரபதி சிவாஜி 'இந்தியாவிலுள்ள அனைத்துக் கோட்டைகளிலும் எவராலும் வெல்ல முடியாத கோட்டை' எனவும், ஆங்கிலேயர்கள் 'கிழக்கின் டிராய்' எனவும் புகழ்ந்தனர்.","difficulty":"medium","topic":"தமிழகக் கோட்டைகள்"},{"id":198,"subject":"gk","testNumber":2,"question":"16ஆம் நூற்றாண்டில் விஜயநகர நாயக்கர்களால் கருங்கற்களால் கட்டப்பட்டதும், ஆழமான அகழி மற்றும் ஜலகண்டேஸ்வரர் கோயிலை உள்ளடக்கியதும், 1806 சிப்பாய்க் கலகம் நடைபெற்றதுமான கோட்டை எது?","options":["வேலூர் கோட்டை","செஞ்சிக் கோட்டை","திருமயம் கோட்டை","செயின்ட் ஜார்ஜ் கோட்டை"],"correctAnswer":0,"explanation":"வேலூர் கோட்டை கி.பி. 1566-இல் விஜயநகரப் பேரரசின் கீழிருந்த சின்ன பொம்மி நாயக்கர் மற்றும் திம்மா ரெட்டி நாயக்கரால் கட்டப்பட்டது. அகன்ற அகழி, சிற்ப வேலைப்பாடுகள் நிறைந்த ஜலகண்டேஸ்வரர் கோயில் ஆகியவற்றைக் கொண்ட இக்கோட்டையில் 1806 ஜூலை 10-இல் இந்திய விடுதலைப் போராட்டத்தின் முன்னோடியான வேலூர் சிப்பாய்க் கலகம் வெடித்தது.","difficulty":"easy","topic":"தமிழகக் கோட்டைகள்"},{"id":199,"subject":"gk","testNumber":2,"question":"திண்டுக்கல் மலைக்கோட்டையை கி.பி. 1605-ஆம் ஆண்டில் கட்டத் தொடங்கிய மதுரை நாயக்க மன்னர் யார்?","options":["முத்து கிருஷ்ணப்ப நாயக்கர்","விசுவநாத நாயக்கர்","சொக்கநாத நாயக்கர்","வீரப்ப நாயக்கர்"],"correctAnswer":0,"explanation":"திண்டுக்கல் மலைக்கோட்டை கி.பி. 1605-இல் மதுரை நாயக்க மன்னர் முத்து கிருஷ்ணப்ப நாயக்கரால் கட்டத் தொடங்கப்பட்டு பின்னர் திருமலை நாயக்கரால் முழுமைப்படுத்தப்பட்டது. 18ஆம் நூற்றாண்டில் இக்கோட்டை மைசூர் அரசர்களான ஹைதர் அலி மற்றும் திப்பு சுல்தானின் முக்கியப் படைத்தளமாக விளங்கியது.","difficulty":"hard","topic":"தமிழகக் கோட்டைகள்"},{"id":200,"subject":"gk","testNumber":2,"question":"திருச்சிராப்பள்ளி மலைக்கோட்டையில் உள்ள 'லலிதாங்குரப் பல்லவேஸ்வர கிருகம்' என்ற புகழ்பெற்ற மேல்குடைவரைக் கோயிலை அமைத்த மன்னர் யார்?","options":["முதலாம் மகேந்திரவர்ம பல்லவர்","பாண்டியன் நெடுஞ்செழியன்","முதலாம் இராஜராஜ சோழன்","திருமலை நாயக்கர்"],"correctAnswer":0,"explanation":"திருச்சிராப்பள்ளி மலைக்கோட்டை மிகப் பழமையான பாறை மீது அமைந்துள்ளது; இங்குள்ள தாயுமானவர் கோயில் மற்றும் உச்சிப்பிள்ளையார் கோயிலோடு பல்லவ மன்னர் முதலாம் மகேந்திரவர்மன் அமைத்த 'லலிதாங்குரப் பல்லவேஸ்வர கிருகம்' மேல்குடைவரைக் கோயிலும், பாண்டியர் காலக் கீழ்குடைவரைக் கோயிலும் வரலாற்றுச் சிறப்பு மிக்கவையாகும்.","difficulty":"medium","topic":"தமிழகக் கோட்டைகள்"}]);
